UPDATE `trans_words` SET `content_loc10`='Ably done, $N. Now we see if my suspicions are correct.' WHERE `word_id` = 178465; -- locales_quest - offerrewardtext : entry=25716
UPDATE `trans_words` SET `content_loc10`='Abner Fizzletorque at Fizzcrank Airstrip wants you to bring him 6 Thick Mammoth Hides.' WHERE `word_id` = 157511; -- locales_quest - objectives : entry=11718
