UPDATE `trans_words` SET `content_loc10`='Archmage Berinand in the Transitus Shield wants you to collect 3 Glacial Splinters and 3 Magic-Bound Splinters from the Ancients in Coldarra.' WHERE `word_id` = 157826; -- locales_quest - objectives : entry=11910
