UPDATE `trans_words` SET `content_loc10`='Assist in Voidwalker\'s Destruction' WHERE `word_id` = 171505; -- locales_quest - ObjectiveText1 : entry=9384
UPDATE `trans_words` SET `content_loc10`='Assist King Varian Wrynn and Lady Jaina Proudmoore in bringing Grand Apothecary Putress to justice! Report to King Varian Wrynn should you succeed.' WHERE `word_id` = 163722; -- locales_quest - objectives : entry=13377
