UPDATE `trans_words` SET `content_loc10`='Assist Lady Jaina Proudmoore in Orgrimmar. Speak to the Warchief of the Horde, Thrall, at Orgrimmar on the continent of Kalimdor.' WHERE `word_id` = 163689; -- locales_quest - objectives : entry=13369
