UPDATE `trans_words` SET `content_loc10`='Blood Orbs shattered' WHERE `word_id` = 162719; -- locales_quest - ObjectiveText1 : entry=13134
UPDATE `trans_words` SET `content_loc10`='Blood Pact With Drakuru' WHERE `word_id` = 158071; -- locales_quest - ObjectiveText1 : entry=11989
UPDATE `trans_words` SET `content_loc10`='Blood Rejek\'s Blade on the corpses of a Sapphire Hive Wasp, a Hardknuckle Charger, and 3 members of the Mistwhisper Tribe. You may blood the sword on either Mistwhisper Oracles or Mistwhisper Warriors. Return to Rejek at Frenzyheart Hill when your task is complete.' WHERE `word_id` = 161029; -- locales_quest - objectives : entry=12734
UPDATE `trans_words` SET `content_loc10`='Blood Watch is one of two forward bases operated by the Hand of Argus. You have already been to the other base, Azure Watch; things are completely different in Bloodmyst. When we first got here, the land was as beautiful as Azuremyst. We even called it Silvergale but now sickness is spreading across the land, worse yet, the blood elves that we were battling on the Exodar survived the crash. This brings me to your assignment: Venture northwest into Bladewood and terminate any blood elves that you find.' WHERE `word_id` = 147980; -- locales_quest - details : entry=9694
UPDATE `trans_words` SET `content_loc10`='Bloodeye Clan ogres & ettins slain' WHERE `word_id` = 184683; -- locales_quest - ObjectiveText1 : entry=27492
UPDATE `trans_words` SET `content_loc10`='Bloodfang Stalker rounded up' WHERE `word_id` = 173526; -- locales_quest - ObjectiveText1 : entry=14212
UPDATE `trans_words` SET `content_loc10`='Bloodguard Lorga wants you to go to the Gimorak\'s Den to the east and obtain 6 Worg Furs.' WHERE `word_id` = 162174; -- locales_quest - objectives : entry=13000
UPDATE `trans_words` SET `content_loc10`='Bloodmage Laurith at the Bloodspore Plains in the Borean Tundra has asked that you use the Pollinated Bloodspore Flower and allow her to observe the results.' WHERE `word_id` = 157516; -- locales_quest - objectives : entry=11719
UPDATE `trans_words` SET `content_loc10`='Bloodmage Laurith at the Bloodspore Plains in the Borean Tundra wants you to recover 10 Bloodspore Carpels.' WHERE `word_id` = 157501; -- locales_quest - objectives : entry=11716
