UPDATE `trans_words` SET `content_loc10`='Bloodmaul Ogres killed' WHERE `word_id` = 151256; -- locales_quest - ObjectiveText1 : entry=10502
UPDATE `trans_words` SET `content_loc10`='Bloodmaul Outpost building cursed' WHERE `word_id` = 151413; -- locales_quest - ObjectiveText2 : entry=10544
UPDATE `trans_words` SET `content_loc10`='Bloodmyst Isle was forever changed by our arrival. The Exodar\'s crash scattered debris all over the islands and I think it\'s beginning to have an adverse effect on the wildlife.$B$BBefore I can be certain of my conclusion, I\'ll need to get a closer look. The crystals seem to have affected the trees the fastest, so it seems that the treants would be the most likely to show symptoms. If you bring me samples of bark from corrupted treants, I can begin my in-depth studies.' WHERE `word_id` = 147537; -- locales_quest - details : entry=9574
UPDATE `trans_words` SET `content_loc10`='Bloodoath sails burned' WHERE `word_id` = 154549; -- locales_quest - ObjectiveText2 : entry=11542
UPDATE `trans_words` SET `content_loc10`='Bloodpetal Observation' WHERE `word_id` = 175279; -- locales_quest - ObjectiveText1 : entry=24695
UPDATE `trans_words` SET `content_loc10`='Bloodpetal, eh? Hmmm... Well, you better explain the plan, and then I\'ll tell you whether or not I can help you.' WHERE `word_id` = 138841; -- locales_quest - offerrewardtext : entry=4142
UPDATE `trans_words` SET `content_loc10`='Bloodrose Datura at Ebon Watch wants you to speak with Commander Falstaav at The Argent Stand.' WHERE `word_id` = 161250; -- locales_quest - objectives : entry=12795
UPDATE `trans_words` SET `content_loc10`='Bloodsail Buccaneers attacking Booty Bay?  This isn\'t the first time that those blaggards have tried something. Booty Bay is impenetrable! Sounds like they might be changing their strategies up, though. Wouldn\'t put it past Firallon to try something crazy. Very well, let\'s see what else they\'re up to.' WHERE `word_id` = 181702; -- locales_quest - offerrewardtext : entry=26611
UPDATE `trans_words` SET `content_loc10`='Bloodsail Buccaneers attacking Booty Bay? They might as well throw themselves off the Overlook Cliffs. Nonetheless, by bringing me this information you have done my fleet of swashbucklers a great service. The Blackwater Raiders thank you.' WHERE `word_id` = 132716; -- locales_quest - offerrewardtext : entry=599
UPDATE `trans_words` SET `content_loc10`='Bloodsail Corsair accused and killed' WHERE `word_id` = 181904; -- locales_quest - ObjectiveText1 : entry=26664
UPDATE `trans_words` SET `content_loc10`='Bloodsnarl Scavenger slain' WHERE `word_id` = 187628; -- locales_quest - ObjectiveText1 : entry=28277
UPDATE `trans_words` SET `content_loc10`='Bloodspore Flower Used' WHERE `word_id` = 157518; -- locales_quest - EndText : entry=11719
UPDATE `trans_words` SET `content_loc10`='Bloodstone Fire Extinguished' WHERE `word_id` = 152725; -- locales_quest - ObjectiveText4 : entry=10874
UPDATE `trans_words` SET `content_loc10`='Bloodtalon Hatchlings rescued' WHERE `word_id` = 175095; -- locales_quest - ObjectiveText1 : entry=24623
UPDATE `trans_words` SET `content_loc10`='Bloody well done! Right-o! Congratulations, $N, for succeeding where others have failed.$B$BI am honored to count you as a comrade of our great hunting party here. No one will ever doubt your expertise in hunting and tracking!$B$BCheers to you, I say! Cheers!' WHERE `word_id` = 131026; -- locales_quest - offerrewardtext : entry=208
UPDATE `trans_words` SET `content_loc10`='Blow the Heth\'Jatari Conch next to a Heth\'Jatari Banner. Kill Fathom-Lord Heth\'Jatar. Luring him into incoming mortar fire will help.' WHERE `word_id` = 185084; -- locales_quest - objectives : entry=27606
