UPDATE `trans_words` SET `content_loc10`='Blow the horn' WHERE `word_id` = 178816; -- locales_quest - ObjectiveText1 : entry=25813
UPDATE `trans_words` SET `content_loc10`='Blow the Unyielding Battle Horn near the Alliance Banner. Kill Urtrak and then return to Althen the Historian at Spinebreaker Post.' WHERE `word_id` = 150278; -- locales_quest - objectives : entry=10250
UPDATE `trans_words` SET `content_loc10`='Blow up Render\'s Valley.' WHERE `word_id` = 181918; -- locales_quest - EndText : entry=26668
UPDATE `trans_words` SET `content_loc10`='Blown up by lightning?$B$B<Rakjak breaks out laughing for a moment.>$B$BYou good hunter. Rakjak like you. Maybe one day you can be honorary Frenzyheart!$B$BOnly maybe though!' WHERE `word_id` = 160120; -- locales_quest - offerrewardtext : entry=12539
