UPDATE `trans_words` SET `content_loc10`='Blue Cauldron disturbed' WHERE `word_id` = 160508; -- locales_quest - ObjectiveText1 : entry=12627
UPDATE `trans_words` SET `content_loc10`='Blue Dragonflight forces at Moonrest Gardens slain' WHERE `word_id` = 158137; -- locales_quest - ObjectiveText1 : entry=12006
UPDATE `trans_words` SET `content_loc10`='Blue Moonstone deactivated' WHERE `word_id` = 172388; -- locales_quest - ObjectiveText1 : entry=13630
UPDATE `trans_words` SET `content_loc10`='Blue Sample Collected' WHERE `word_id` = 163528; -- locales_quest - ObjectiveText1 : entry=13320
UPDATE `trans_words` SET `content_loc10`='Bluegill Murloc slain' WHERE `word_id` = 178775; -- locales_quest - ObjectiveText1 : entry=25801
UPDATE `trans_words` SET `content_loc10`='Blueleaf tubers are a delicacy around the world!  But they\'re rare, very rare. The only place to find them is here in the Barrens, deep in the earth, in Razorfen Kraul.$B$BAnd even then, they\'re impossible to find unless you know just where to look!  That\'s why I\'ve trained these snufflenose gophers to find them for me. They have great noses and can smell a tuber from fifty paces away.$B$BIt won\'t be easy, but if you get me some tubers I\'ll pay you handsomely.' WHERE `word_id` = 135178; -- locales_quest - details : entry=1221
UPDATE `trans_words` SET `content_loc10`='Blurgh...$B$BCould you... ugh... could you please... URGH!$B$BExcuse me, I\'m still a little... ugh, my stomach. If you\'re going to Bloodvenom Post to the west, could you please HUUURGH...$B$BJust... just put what\'s left of my friends out of their misery. Go RIGHT NOW. For your own good. Uuuuurghh...' WHERE `word_id` = 187364; -- locales_quest - details : entry=28214
