UPDATE `trans_words` SET `content_loc10`='Buy a gryphon to Ironforge from the gryphon master Thorgrum Borrelson, then bring Brock\'s List to Golnir Bouldertoe in Ironforge.' WHERE `word_id` = 141291; -- locales_quest - objectives : entry=6391
UPDATE `trans_words` SET `content_loc10`='Buy a gryphon to Kharanos from the gryphon master Gryth Thurden, then bring the Honorary Cleavers to Gremlock Pilsnor in Kharanos.' WHERE `word_id` = 168056; -- locales_quest - objectives : entry=6392
UPDATE `trans_words` SET `content_loc10`='Buy a wind rider to Bloodhoof Village from the wind rider master Tal, then bring Ahanu\'s Leather Goods to Varg Whisperwind.' WHERE `word_id` = 168034; -- locales_quest - objectives : entry=6364
UPDATE `trans_words` SET `content_loc10`='Buy a wind rider to Orgrimmar from the wind rider master Devrak, then bring Zargh\'s Meats to Gryshka in Orgrimmar.' WHERE `word_id` = 141260; -- locales_quest - objectives : entry=6384
UPDATE `trans_words` SET `content_loc10`='Buy a wind rider to Orgrimmar from the wind rider master Devrak, then bring Zargh\'s Meats to Gryshka in Orgrimmar.' WHERE `word_id` = 337559; -- locales_quest - CompletedText : entry=6384
