UPDATE `trans_words` SET `content_loc10`='Disrupt the cultist rituals in the Drag, the Valley of Honor, and near the city\'s West Gate by reading the incorrect words from the Book of Incantations.' WHERE `word_id` = 171976; -- locales_quest - objectives : entry=27799
UPDATE `trans_words` SET `content_loc10`='Disrupt the cultist rituals in the Dwarven District, the Park, and the Cathedral District by reading the incorrect words from the Book of Incantations.' WHERE `word_id` = 171970; -- locales_quest - objectives : entry=27780
UPDATE `trans_words` SET `content_loc10`='Disrupt the meeting between Sanath Lim-yo and the thief in the catacombs beneath the Cathedral of Light.' WHERE `word_id` = 190846; -- locales_quest - objectives : entry=29403
UPDATE `trans_words` SET `content_loc10`='Disrupt the meeting between Sanath Lim-yo and the thief in the Ruins of Lordaeron.' WHERE `word_id` = 190862; -- locales_quest - objectives : entry=29427
UPDATE `trans_words` SET `content_loc10`='Distract Karr\'gonn and slay Dark Cultist Azennios at the Seat of the Chosen in Hyjal.' WHERE `word_id` = 177055; -- locales_quest - objectives : entry=25308
UPDATE `trans_words` SET `content_loc10`='Distribute the Altered Leaflets to 6 Theramore Guards.' WHERE `word_id` = 183842; -- locales_quest - objectives : entry=27212
UPDATE `trans_words` SET `content_loc10`='Distribute the Ironforge Rations to 6 Ironforge Guards.' WHERE `word_id` = 190311; -- locales_quest - objectives : entry=29351
UPDATE `trans_words` SET `content_loc10`='Disturb 8 Ritual Gems.' WHERE `word_id` = 172485; -- locales_quest - objectives : entry=13683
UPDATE `trans_words` SET `content_loc10`='Disturb Mereldar Plague Cauldron' WHERE `word_id` = 184514; -- locales_quest - EndText : entry=27454
UPDATE `trans_words` SET `content_loc10`='Disturbing news indeed. This stuff\'s much more like what you\'d see in Felwood than in Winterspring...' WHERE `word_id` = 188260; -- locales_quest - offerrewardtext : entry=28467
UPDATE `trans_words` SET `content_loc10`='Dithers said you\'d deliver the goods, and deliver you have! A deal is a deal; let me pack the fragments into the mold for you.$B$BDid Dithers imbue them already? Excellent... otherwise, it would have been a long trip back to the Bulwark for you.' WHERE `word_id` = 140398; -- locales_quest - offerrewardtext : entry=5514
UPDATE `trans_words` SET `content_loc10`='Dithers, you\'ve done it again!  These are perfect.' WHERE `word_id` = 176170; -- locales_quest - offerrewardtext : entry=25056
UPDATE `trans_words` SET `content_loc10`='Dive into Danger.' WHERE `word_id` = 152092; -- locales_quest - EndText : entry=10716
UPDATE `trans_words` SET `content_loc10`='Dive to the bottom of Stillwhisper Pond and retrieve the Azure Phial for Instructor Antheol.' WHERE `word_id` = 146869; -- locales_quest - objectives : entry=9402
UPDATE `trans_words` SET `content_loc10`='Dizzy Dina has asked you to acquire 5 Ether-Energized Flesh and return them to her at Toshley\'s Station in the Blade\'s Edge Mountains.' WHERE `word_id` = 151940; -- locales_quest - objectives : entry=10671
UPDATE `trans_words` SET `content_loc10`='Dizzy Dina wants you to kill 10 Ridgespine Stalkers. After you have done so, return to her at Toshley\'s Station in the Blade\'s Edge Mountains.' WHERE `word_id` = 151737; -- locales_quest - objectives : entry=10620
UPDATE `trans_words` SET `content_loc10`='Dizzy One-Eye in Booty Bay wants you to retrieve his eye from the Bloodsail Buccaneers.' WHERE `word_id` = 132613; -- locales_quest - objectives : entry=576
UPDATE `trans_words` SET `content_loc10`='Do a chicken emote at Innkeeper Firebrew, and in exchange you\'ll receive an Ironforge Mint!' WHERE `word_id` = 143363; -- locales_quest - objectives : entry=8353
UPDATE `trans_words` SET `content_loc10`='Do a chicken emote at Innkeeper Norman, and in exchange you\'ll receive an Undercity Mint!' WHERE `word_id` = 143367; -- locales_quest - objectives : entry=8354
UPDATE `trans_words` SET `content_loc10`='Do a dance emote at Innkeeper Pala, and in exchange you\'ll receive Thunder Bluff Marzipan!' WHERE `word_id` = 143393; -- locales_quest - objectives : entry=8360
UPDATE `trans_words` SET `content_loc10`='Do a dance emote at Innkeeper Saelienne, and in exchange you\'ll receive Darnassus Marzipan!' WHERE `word_id` = 143382; -- locales_quest - objectives : entry=8357
UPDATE `trans_words` SET `content_loc10`='Do a flex emote at Innkeeper Allison, and in exchange you\'ll receive Stormwind Nougat!' WHERE `word_id` = 271998; -- locales_quest - objectives : entry=8356
UPDATE `trans_words` SET `content_loc10`='Do a flex emote at Innkeeper Gryshka, and in exchange you\'ll receive Orgrimmar Nougat!' WHERE `word_id` = 143391; -- locales_quest - objectives : entry=8359
UPDATE `trans_words` SET `content_loc10`='Do a silly dance for Ruumbo.' WHERE `word_id` = 186536; -- locales_quest - objectives : entry=27995
UPDATE `trans_words` SET `content_loc10`='Do a train emote at Kali Remik, and in exchange you\'ll receive a Darkspear Gumdrop!' WHERE `word_id` = 276053; -- locales_quest - objectives : entry=8358
UPDATE `trans_words` SET `content_loc10`='Do a train emote at Talvash del Kissel, and in exchange you\'ll receive a Gnomeregan Gumdrop!' WHERE `word_id` = 143371; -- locales_quest - objectives : entry=8355
UPDATE `trans_words` SET `content_loc10`='Do any of these titles interest you, $N?' WHERE `word_id` = 132628; -- locales_quest - offerrewardtext : entry=579
UPDATE `trans_words` SET `content_loc10`='Do I know you, $R? Sounds like another one of Ragnaros\' minions. I don\'t like the sound of that.' WHERE `word_id` = 186412; -- locales_quest - offerrewardtext : entry=27965
UPDATE `trans_words` SET `content_loc10`='Do my eyes deceive me or is there an ogre hunting party over yonder? What could ogres be doing this far from their mound? I don\'t like this one bit, stranger. First Murkbloods and now ogres. We just don\'t have the manpower to handle all of these threats to our land.$B$BCould you investigate the ogre presence to the east for us? Their forward camp is about 200 paces east of here. You\'ll know you\'re at the right place if you see the Boulderfist hunters. Kill them to find the plans!' WHERE `word_id` = 148928; -- locales_quest - details : entry=9917
UPDATE `trans_words` SET `content_loc10`='Do my eyes deceive me? Impossible! Where did you... How...$B$BPerhaps now a rift can be opened, returning us to our homeland.' WHERE `word_id` = 136914; -- locales_quest - offerrewardtext : entry=2521
UPDATE `trans_words` SET `content_loc10`='Do not be alarmed by what you might see once the effect has taken hold! These spirits are all around us - always. The potion allows your mind to be able to understand and ultimately see the spirits. You will need to be under its influence if you are to speak with Mother Kashur.$B$BYou will find her a great ways to the southwest, at the Ancestral Grounds.' WHERE `word_id` = 272888; -- locales_quest - details : entry=10081
UPDATE `trans_words` SET `content_loc10`='Do not be alarmed, $N. I am close to you, waiting in the shadows. You\'ve done well. You must continue the mission here - I am too valuable to risk my life against petty criminals like these.' WHERE `word_id` = 185984; -- locales_quest - offerrewardtext : entry=27842
UPDATE `trans_words` SET `content_loc10`='Do not be alarmed, young $R. I am Zaetar, son of Cenarius, and I come to you for your assistance.$B$BLong ago, I made the mistake of mating with Princess Theradras, a powerful earth elemental aligned with the Old Gods. Our children, the centuar Kahns, turned on me upon birth and slew me mercilessly. Now, Theradras\' taint runs deep and threatens far more than just Maraudon.$B$BCome slay her and free my spirit so that we may restore Desolace to a place of verdant life and promise, as Cenarius would want.' WHERE `word_id` = 185412; -- locales_quest - details : entry=27692
UPDATE `trans_words` SET `content_loc10`='Do not burden A\'dal with petty inquisitions, $C. That just might be the most powerful being you ever come face to face with.$B$BYou do not look familiar. I suppose you want to learn about the city?$B$BYou\'ll have to excuse me if I don\'t give you a tour myself, but I\'m a bit busy discussing strategy with A\'dal. Perhaps you\'ll find a summoned servant acceptable in my stead?  Excellent!' WHERE `word_id` = 150103; -- locales_quest - details : entry=10211
UPDATE `trans_words` SET `content_loc10`='Do not concern yourself with the world below Teldrassil for now. There will be time for that later. Go now and speak to the others in Shadowglen--they can tell you more about what events have transpired. Help them in any way you can, and anytime you feel you need more training, come back to me and I will teach you what I can.' WHERE `word_id` = 137878; -- locales_quest - offerrewardtext : entry=3119
UPDATE `trans_words` SET `content_loc10`='Do not draw attention to our conversation. Adaris would not approve.$B$BI belong to the lowest caste of arakkoa, $N. During Terokk\'s rule I would\'ve been sacrificed to the dark powers worshipped by his talonpriests. If what you say is true and the talonpriests are seeking Terokk\'s return, then you must prevent them from succeeding - regardless of what your leader says!$B$BI\'ve something to offer you that you\'ll find useful. There is a package at my old dwelling in Upper Veil Shil\'ak. Bring it to me!' WHERE `word_id` = 153474; -- locales_quest - details : entry=11056
UPDATE `trans_words` SET `content_loc10`='Do not dwell upon her suffering, $N. The beast was corrupt - a product of dark magic. You have done the Alliance a great service and you shall be rewarded.' WHERE `word_id` = 139277; -- locales_quest - offerrewardtext : entry=4701
UPDATE `trans_words` SET `content_loc10`='Do not fear the bears in this grove, $C - I have pacified them for the moment.$B$BMy concern at present is for the welfare of the bear cubs. The fires drove the little ones up the trees, where they\'ve gotten stuck. We\'ve got to get those bears safely to the ground!$B$BFlying creatures frighten them, so you\'ll have to climb the trees yourself. Look for footholds at the trunks. Climb the trees, grab the bear cubs, and toss them - GENTLY! - onto the target here.$B$BNothing can go wrong with this plan.' WHERE `word_id` = 177524; -- locales_quest - details : entry=25462
UPDATE `trans_words` SET `content_loc10`='Do not fear, $N. While you are here we will speak using our minds.$B$BI am grateful to Farseer Nobundo for sending you to me. There is a great disturbance that is polluting the waters on and around Bloodmyst Isle. Not even the blind would fail to notice the effect this is having on its creatures and the environment.$B$BYou and I will work together to stop this corruption before it spreads further.' WHERE `word_id` = 147245; -- locales_quest - offerrewardtext : entry=9501
UPDATE `trans_words` SET `content_loc10`='Do not feel sorry for me. Those were my friends that you saw at Quel\'lithien Lodge, but they were already as good as dead.' WHERE `word_id` = 184806; -- locales_quest - offerrewardtext : entry=27521
UPDATE `trans_words` SET `content_loc10`='Do not hesitate; tell me why you have come.$B$BOh, yes? Hmm. Well.$B$BThank you for bringing this straight to me; it is always best to go right to the top... But... Yes. The druids of the Cenarion Circle have known of the Wildkin for some time. That they are pets of Elune, and were chosen to guard the most sacred of places.$B$BSo while this isn\'t news, I definitely compliment you on your effort. Here, take this -- it is something that seems suitable for such a deed.' WHERE `word_id` = 139545; -- locales_quest - offerrewardtext : entry=4902
UPDATE `trans_words` SET `content_loc10`='Do not let Hellscream dissuade you from your duties as a soldier of the Horde, $R. He bears a terrible burden in these frozen wastes, with the outcome of his charge resulting in victory over the Scourge or the extinction of all life on Azeroth. It is for this reason that we require your strength and wisdom.$B$BThe Scourge have begun their assault upon this fortress. Our soldiers steady the line, but are in desperate need of backup. Report to Razgor. He is stationed directly outside of Warsong Hold.' WHERE `word_id` = 156950; -- locales_quest - details : entry=11596
UPDATE `trans_words` SET `content_loc10`='Do not regret the part that you played in the cycle of life. Birth, death, and rebirth are all part of the natural order.' WHERE `word_id` = 159741; -- locales_quest - offerrewardtext : entry=12454
UPDATE `trans_words` SET `content_loc10`='Do not think me unduly harsh, $N. Stillblade knew well what he was being sent to do. He understood and accepted his duty and is an example for all aspiring Blood Knights.$B$BMy words are no eulogy, $N. Stillblade\'s service to us is far from over and you will be the instrument of his resurrection.$B$BYour education in the order\'s ways has just begun. With the betrayal of Kael\'thas and the loss of our power source, you must learn new methods of wielding the Light. Seek out Magister Astalor Bloodsworn.' WHERE `word_id` = 147921; -- locales_quest - details : entry=9681
UPDATE `trans_words` SET `content_loc10`='Do not think that I have forgotten what you did for my people in Nagrand, $N. Hellscream never forgets.$B$BFor that I am indebted to you and it is why I give you this chance now: run. Leave this place and never look back.$B$BReturn to your home and say a prayer for the dying.' WHERE `word_id` = 156913; -- locales_quest - offerrewardtext : entry=11586
UPDATE `trans_words` SET `content_loc10`='Do not weep for Alystros. He has dedicated his eternal life to the defense of the Emerald Dragonshrine and will be reborn.$B$BHopefully when he returns to us, he will not be gripped with the confusion of the Emerald Nightmare that seems to have taken hold of The Dreamer.' WHERE `word_id` = 159750; -- locales_quest - offerrewardtext : entry=12456
UPDATE `trans_words` SET `content_loc10`='Do not worry about me. My wounds are deep and death will soon come to me.$B$BIt is all up to you now... you must stop the Twilight\'s Hammer.$B$BThe Old Gods they worship have granted them power over the restless water spirits... but that power is tenuous. Channel Elune\'s presence through this orb once the elementals have been defeated.$B$BUse the power of Elune to banish the spirits permanently.' WHERE `word_id` = 172073; -- locales_quest - details : entry=13523
UPDATE `trans_words` SET `content_loc10`='Do not worry, $N, I am not sending you to see Syurna. Erion requires your presence at the Cenarion Enclave. Make haste!' WHERE `word_id` = 136717; -- locales_quest - details : entry=2259
UPDATE `trans_words` SET `content_loc10`='Do not worry, $R.$B$BThe eggs they found were but a fraction of our hidden stores within Azjol-Nerub.$B$BOur mighty kingdom shall be reborn.' WHERE `word_id` = 191393; -- locales_quest - offerrewardtext : entry=29808
UPDATE `trans_words` SET `content_loc10`='Do something cool with the lumberjack.' WHERE `word_id` = 175563; -- locales_quest - objectives : entry=24867
UPDATE `trans_words` SET `content_loc10`='Do the "train" for Kali Remik' WHERE `word_id` = 143389; -- locales_quest - EndText : entry=8358
UPDATE `trans_words` SET `content_loc10`='Do the "train" for Talvash' WHERE `word_id` = 143373; -- locales_quest - EndText : entry=8355
UPDATE `trans_words` SET `content_loc10`='Do what you must to defeat our enemies, $C. Even if it means channeling the Light.$B$B<Jin\'rokh shudders.>' WHERE `word_id` = 142743; -- locales_quest - offerrewardtext : entry=8046
UPDATE `trans_words` SET `content_loc10`='Do you bring word from central command?' WHERE `word_id` = 136593; -- locales_quest - offerrewardtext : entry=2041
UPDATE `trans_words` SET `content_loc10`='Do you feel it, $C?  The elements are uneasy. We members of the Earthen Ring have struggled to find the cause of the unrest. Thus far we have been unsuccessful and now turn to others that may aid us. Speak with Earthmender Norsala in Orgrimmar and see what tasks she may have for you.' WHERE `word_id` = 171925; -- locales_quest - details : entry=27308
UPDATE `trans_words` SET `content_loc10`='Do you feel it, $C?  The elements are uneasy. We members of the Earthen Ring have struggled to find the cause of the unrest. Thus far we have been unsuccessful and now turn to others that may aid us. Speak with Erunak Stonespeaker in Stormwind and see how you might be able to aid us.' WHERE `word_id` = 171922; -- locales_quest - details : entry=27307
UPDATE `trans_words` SET `content_loc10`='Do you feel it, $N? That sensation is raw power coursing through your body. Such a thing cannot exist for mortals.$B$BThe front lines are now dismantled. The geist will finish the job and prepare the grounds for Razuvious. We turn our attention now to more tactical targets.' WHERE `word_id` = 276616; -- locales_quest - offerrewardtext : entry=12678
UPDATE `trans_words` SET `content_loc10`='Do you feel the closeness, $N? Surely you feel a true bond forming between you and your falcon. Would you believe me if I told you that when the time is right you\'ll be able to see through the eyes of your bird? Aye, it is the ultimate level of falconry.$B$BBut first you must hunt more! The bird must hone and quicken its reflexes. Send it against a more formidable opponent! The fjord hawks of the region make the tops of the trees around us their homes. They shall be your next target!' WHERE `word_id` = 156674; -- locales_quest - details : entry=11468
UPDATE `trans_words` SET `content_loc10`='Do you have a copy of the Darkmoon Field Guide, friend? It\'s a most useful book to carry with you.$B$BIt can help you find and identify valuable artifacts throughout your travels in Azeroth. Its detailed descriptions make it easy to decide if you\'ve found your five hundredth brass button or that rare treasure the Darkmoon Faire\'s collectors crave.' WHERE `word_id` = 191206; -- locales_quest - details : entry=29601
UPDATE `trans_words` SET `content_loc10`='Do you have any idea what you\'ve been carrying around, $C?$B$BThe cave beasts you\'ve been harvesting have no traditional method of excreting their waste. You might want to wash your hands...$B$BThank you for the thought, but if you come across any more of these please keep them for yourself.' WHERE `word_id` = 163028; -- locales_quest - offerrewardtext : entry=13204
UPDATE `trans_words` SET `content_loc10`='Do you hear that, $N? That\'s the sweet hum of the refrigeration kicking in. We\'ll be able to store our inventory down there in no time. Thank you!' WHERE `word_id` = 186701; -- locales_quest - offerrewardtext : entry=28047
UPDATE `trans_words` SET `content_loc10`='Do you know anything about the naaru?  They\'re these angelic beings that have been helping the draenei for a really long time. I\'ve seen a bunch around Shattrath.$B$BThey say that one naaru, O\'ros, was with the Exodar when it traveled to your homeworld. I should like to see for myself.$B$BCan you take me there?  I bet we could get there fast by using one of the portals inside the Terrace of Light at Shattrath City!  When we get there, if you get lost, we could always just look at your map.' WHERE `word_id` = 153061; -- locales_quest - details : entry=10956
UPDATE `trans_words` SET `content_loc10`='Do you know how hard it is to get fresh water in Stranglethorn?  It\'s no wonder that the nagas guard their shrine so ferociously! Alright, let\'s get this mix started!' WHERE `word_id` = 182421; -- locales_quest - offerrewardtext : entry=26817
UPDATE `trans_words` SET `content_loc10`='Do you know how many ranger lords exist in this world? How many human ranger lords have ever existed?$B$BNathanos\' accomplishments were unprecedented. He was a tactical genius, responsible for Alliance victories spanning a decade of conflict.$B$BAnd now... the champion of the Forsaken.$B$BNo. This cannot be. Order must be restored.$B$BGather an army, $N. Return to the Plagues with your army and destroy the Blightcaller.$B$BI wish you luck, $N. Truly, you will need it for this battle.' WHERE `word_id` = 141149; -- locales_quest - details : entry=6187
UPDATE `trans_words` SET `content_loc10`='Do you know Sven? Now, there is a man who does the work of the Light! He and his followers keep a camp at the northwestern edge of Duskwood.$B$BUnfortunately, because they are so few, they cannot even spare a man to fetch supplies from town. Will you deliver these supplies to him?' WHERE `word_id` = 130828; -- locales_quest - details : entry=164
UPDATE `trans_words` SET `content_loc10`='Do you know what I hate worse than being wrong? Losing gold on a bet that you couldn\'t pull it off, sweetheart.$B$BOutstanding! With those three dead their forces should be in disarray. And with their artillery up there silenced we\'ll have an easier time getting close enough to take the citadel!$B$BI have a feeling there\'s more to this than meets the eye, though' WHERE `word_id` = 147543; -- locales_quest - offerrewardtext : entry=9575
UPDATE `trans_words` SET `content_loc10`='Do you know what that was? Gnomish engineering at its finest! S.T.O.U.T. took the abuse like a champ!$B$BI think you\'re ready now to take on the Dark Irons if they show up again.' WHERE `word_id` = 154769; -- locales_quest - offerrewardtext : entry=12022
UPDATE `trans_words` SET `content_loc10`='Do you know what the troops on the front lines call these? Priests in a bottle...$B$B<Packmaster Stonebruiser sings.>$B$B"I\'m your priest in a bott-le baby... you gotta drink me the right way..."$B$BWhat\'s the matter sonny? It\'s a very popular song around these parts.' WHERE `word_id` = 145165; -- locales_quest - offerrewardtext : entry=9202
UPDATE `trans_words` SET `content_loc10`='Do you know what would have happened if you had not intercepted this missive, $N?$B$B<Nazgrel nods.>$B$BThe entirety of the Legion army in Hellfire would have been knocking on our door. There is no way that we could have survived such an assault.$B$BThere is only one way to make sure that these orders never reach the Legion Front. You must travel to the Pools of Aggonar, west of here, and slay this Arazzius creature.$B$BDo this and I will see to it that the Warchief grants you a commendation.' WHERE `word_id` = 150890; -- locales_quest - details : entry=10401
UPDATE `trans_words` SET `content_loc10`='Do you know who the Knights of the Silver Hand were? They were the original paladins of the Light, and from their ranks came knights who would later join the Argent Dawn or the Scarlet Crusade. Though many have gone astray, they still possess valuable relics of the Silver Hand.$B$BDeep in Stratholme, under the watchful eye of Instructor Galford, volumes of the Annals of the Silver Hand survive. Any volumes you could recover would be a fitting addition to the rededicated Light\'s Hope Chapel.' WHERE `word_id` = 189208; -- locales_quest - details : entry=28755
UPDATE `trans_words` SET `content_loc10`='Do you know why Mortuus appends \'nub\' to your name, $N? Because he is an incompetent sycophant that has trouble seeing through his oversized helmet. \'NUB\' is your classification. You are now part of the NEW UNDERCITY BATALLION.$B$BBut enough with the comedy! I sent Deathstalker Yorick on a shadow operation two days ago. Her goal was to get information on the Gilneas Liberation Front and return. Three days and no word from her.$B$BHead southwest to the Ivar Patch and look for Yorick, $N.' WHERE `word_id` = 183248; -- locales_quest - details : entry=27039
UPDATE `trans_words` SET `content_loc10`='Do you know why the Horde destroys? The Horde destroys because they cannot comprehend beauty. They fear it and that which they fear they must destroy. Why else would they destroy Thal\'darah Grove? Together, we will make them understand. They will know that what they do comes at a great cost.' WHERE `word_id` = 179140; -- locales_quest - offerrewardtext : entry=25891
UPDATE `trans_words` SET `content_loc10`='Do you live for the hunt as I do, $C?  Do you seek the quietude that comes as you stalk your prey?  Would you know what it is to honor the last heartbeats of your fallen quarry?  I will help you to achieve this.$B$BNagrand is a lush land, full of life in the midst of this broken world. Bring down a handful of the windrocs and then we will speak more.$B$BYou can find them in many places nearby in all directions around our camp.' WHERE `word_id` = 148678; -- locales_quest - details : entry=9854
UPDATE `trans_words` SET `content_loc10`='Do you need a ride back to Dolanaar?' WHERE `word_id` = 168012; -- locales_quest - offerrewardtext : entry=6342
UPDATE `trans_words` SET `content_loc10`='Do you not yet understand? The journey was the destination. Can you not feel the battle scars? The pain you underwent?$B$BHaving survived the ordeal, you are a more powerful being. Much more powerful. This breastplate is merely a reflection of your own innate abilities.' WHERE `word_id` = 140007; -- locales_quest - offerrewardtext : entry=5166
UPDATE `trans_words` SET `content_loc10`='Do you now understand the importance of our mission here? Crowley and his Alliance dogs must be stopped!' WHERE `word_id` = 183486; -- locales_quest - offerrewardtext : entry=27098
UPDATE `trans_words` SET `content_loc10`='Do you question your master? Neither does Mah\'duun.$B$BThe blood of the centurions of the Shattered Hand clan is what I seek. You will find them within the Shattered Halls of Hellfire Citadel.$B$BIf you want the bounty, you will not return until you have slain them all.' WHERE `word_id` = 154184; -- locales_quest - details : entry=11364
UPDATE `trans_words` SET `content_loc10`='Do you see a problem with these wind riders, $N? They\'re not riding the wind! Every flight I send aloft gets peppered by night elf snipers.$B$BTalrendis sharpshooters are holed up in the southern-most tower, against the mountains. I sent one of these little goblin scrubs to take care of the tower, but I haven\'t heard a word from him. Go find Bombardier Captain Smooks and beat him with the hurry stick!' WHERE `word_id` = 174474; -- locales_quest - details : entry=14475
UPDATE `trans_words` SET `content_loc10`='Do you see it, $N? From the ridge southwest of here... plumes of black smoke curling into the sky.$B$BMount Hyjal is burning.$B$BIf the fires have raced this far up the mountain, surely they threaten the Grove of Aessina and all of our forces there. Can you investigate?$B$BSpeak with Laina Nightsky near the Grove of Aessina. Last I heard, she was fighting off the assault.' WHERE `word_id` = 178093; -- locales_quest - details : entry=25630
UPDATE `trans_words` SET `content_loc10`='Do you see now?  Sending your men against the prince\'s armies just swells their numbers.$B$BI don\'t expect you to understand... you\'ll probably just end up like the others. You\'d best return to whoever sent you. They might be worried.' WHERE `word_id` = 163632; -- locales_quest - details : entry=13348
UPDATE `trans_words` SET `content_loc10`='Do you see now? For doing what was needed to drive the demons from these lands, my master was banished.$B$BNow these druids pick up the pieces, patting themselves on the back for scrubbing the remaining vestiges of the legion\'s forces.$B$BBut that is not why I killed them.' WHERE `word_id` = 187543; -- locales_quest - offerrewardtext : entry=28257
UPDATE `trans_words` SET `content_loc10`='Do you see the trail below us, $N? That is MY trail. And if the Alliance dogs choose to use my trail, they\'d best be looking over their shoulder.$B$BIt\'s time to collect my toll! Slay the footsoldiers from Honor\'s Stand and see if we can\'t send them scurrying back to their walls.$B$BBe sure to take out at least one of their officers patrolling the road. They need to realize that nobody is safe.' WHERE `word_id` = 174847; -- locales_quest - details : entry=24517
UPDATE `trans_words` SET `content_loc10`='Do you see them walking around us? The Ancestral Grounds are normally quiet and undisturbed.$B$BAs of late, the ancestral spirits have risen and are extremely agitated. Something is causing a great disturbance to the spirits. We must discover what that something could be, but first, we must put the immediate threat to rest.$B$BThese ghosts that you see walking about are not truly the ancestors but a representation of their state of being. You must destroy the agitated orc spirits. Do this and return to me.' WHERE `word_id` = 149563; -- locales_quest - details : entry=10082
UPDATE `trans_words` SET `content_loc10`='Do you see them, along the shore? Such magnificent specimens! Look at their primitive society in action, working like a well-oiled machine from the lowliest grunt to their leader, who I\'ve named "King Burgrurble."$B$BI must study their brains.$B$BCan you procure an intact Slobberfang Murloc brain stem for me? Kill them - for science!' WHERE `word_id` = 172543; -- locales_quest - details : entry=13802
UPDATE `trans_words` SET `content_loc10`='Do you see them?? By Gazlowe\'s horrific halitosis, I will have those eggs! Say, you look like you might be of some use.$B$BI\'ll tell you what, $R; if you gather a few items for me to make my Jump-a-tron 4000 functional, I\'ll give you a key that will let you operate the machine as well! What can you do with a Jump-a-tron 4000 you say? What can\'t you do is more like it...$B$BI\'ll need air elemental gas from the air elementals of Nagrand. They\'re all over the place so don\'t ask me where to find \'em!' WHERE `word_id` = 149680; -- locales_quest - details : entry=10109
UPDATE `trans_words` SET `content_loc10`='Do you see those vrykul buildings on the bluffs to the northeast? The vrykul call that place Nifflevar. It\'s where most of their harpoon attacks on our frigates originate.$B$BWell guess what? The time for payback has come, $N. I need you to take this harpoon control mechanism and meet up with Lieutenant Icehammer, who is hiding out in a vrykul building northwest of Nifflevar.$B$BWhen you\'re ready I\'ll place you on the back of one of our gryphons and zip you right to him! ' WHERE `word_id` = 273928; -- locales_quest - details : entry=11427
UPDATE `trans_words` SET `content_loc10`='Do you see what Deathwing\'s minions have done?  Great Orsis is now all but buried in the sand!' WHERE `word_id` = 187022; -- locales_quest - offerrewardtext : entry=28135
UPDATE `trans_words` SET `content_loc10`='Do you see what they\'re doing here? They\'re affixing armored plates onto the Dragonkin. A page out of Deathwing\'s book, I suppose.$B$BThose Twilight Juggernauts look like they\'ll be invincible once they\'re complete. There\'s got to be a way around that armor plating!$B$BRun out there and fetch some of the Twilight armor plates that are waiting to be installed. We\'ll figure out how to beat this.' WHERE `word_id` = 178648; -- locales_quest - details : entry=25758
UPDATE `trans_words` SET `content_loc10`='Do you smell it?$B$B<Valanar sniffs at the air.>$B$BFresh meat... The scent of Scarlet Crusader wafts through the air.$B$B<Valanar salivates.>$B$BApologies, death knight, I\'m sure you\'re not interested in my choice of fine cuisine. You are here to work! To lead the charge! Yes... I know. The Lich King has told me all that I need to know about you, $N.$B$BThe time for bloodshed is now.' WHERE `word_id` = 336037; -- locales_quest - offerrewardtext : entry=12670
UPDATE `trans_words` SET `content_loc10`='Do you smell that delicious aroma? It\'s my secret recipe, $N--fresh strider stew. Delicious!$B$BPerhaps you would be interested in learning the recipe?$B$BBefore I teach you the recipe, you will need to prove that you can handle the beasts.$B$BNow, I don\'t expect you to go out and tame one and ride it back to me, but if you can kill a few and bring back some of their succulent meat, I may be persuaded to show you the ways of strider stew.' WHERE `word_id` = 136639; -- locales_quest - details : entry=2178
UPDATE `trans_words` SET `content_loc10`='Do you speak deer? It\'s all in the nose.$B$B<She points to her nose.>$B$BThe does have fled the fires, but their little fawns - Some of them are still trapped in the burning and the hurt!$B$BGo back into the Inferno and escort three injured fawns back here to their mothers right here beside me.$B$BPlease save the little fawns, or I\'ll give you the big eyes!$B$B<Her eyes grow big and dewy.>' WHERE `word_id` = 177319; -- locales_quest - details : entry=25392
UPDATE `trans_words` SET `content_loc10`='Do you think often of your family, $N? There were a number of families aboard the Exodar, but I\'ve heard of very few being reunited.$B$BI, myself, am looking for traces of my husband Galaen, who was a technician in the Cryo-Core. The wreckage of it is located to the west, and it\'s swarming with blood elves!$B$BI must find out what became of Galaen! Even news of his death is better than never knowing. My husband will be wearing a pendant identical to my own; they were a gift from my sister.' WHERE `word_id` = 147551; -- locales_quest - details : entry=9578
UPDATE `trans_words` SET `content_loc10`='Do you think she ever saw an oracle before? We might be the first one ever to meet her! We thinks she liked us, but we\'re not sure. She doesn\'t talk a lot. Nope. But that was fun!' WHERE `word_id` = 164543; -- locales_quest - offerrewardtext : entry=13954
UPDATE `trans_words` SET `content_loc10`='Do you think the apprentices mind freezing all that ice cream? I wish I got to make ice cream at school. That would make lessons a lot more fun, don\'t you think?' WHERE `word_id` = 189859; -- locales_quest - offerrewardtext : entry=29119
UPDATE `trans_words` SET `content_loc10`='Do you think William\'s death was a random killing by the Scourge?  Things sure seem fishy.$B$BSomething\'s up. We must find Thassarian.' WHERE `word_id` = 156966; -- locales_quest - offerrewardtext : entry=11600
UPDATE `trans_words` SET `content_loc10`='Do you think you could help me find my way back to my friend, Rockbiter? He was supposed to be watching me... But I do have a tendency to wander off now and then. There are just so many things to see, and I get so distracted.$B$BThere is one thing that will always work to get my attention, though.$B$BInside this chest, you\'ll find a bell that is very precious to me. I just love the sound of it. You have my word, if I wander off, all you have to do is ring it and I\'ll come running back.' WHERE `word_id` = 137237; -- locales_quest - details : entry=2845
UPDATE `trans_words` SET `content_loc10`='Do you think you could help me get out of this cage?  It\'s a bit cramped.' WHERE `word_id` = 191244; -- locales_quest - offerrewardtext : entry=29640
UPDATE `trans_words` SET `content_loc10`='Do you truly believe that you will make it to your rendezvous point with me in custody? You actually expected to break into a heavily fortified Blackrock fortress to capture a prized asset of theirs without alerting anyone or anything to your presence?$B$BYou will be destroyed!' WHERE `word_id` = 271049; -- locales_quest - details : entry=4121
UPDATE `trans_words` SET `content_loc10`='Do you understand what must be done? Find the sons of Oronok. Find my boys...' WHERE `word_id` = 151339; -- locales_quest - offerrewardtext : entry=10519
UPDATE `trans_words` SET `content_loc10`='Do you understand why I have you assassinate the dragons, yet spare the mortals? It isn\'t their fault. They must seek out their own destiny, free from the meddling of my kind.$B$BWe are nearing the end of our mission, and it is time for you to seek out your own destiny as well. I can continue to augment your weapons, but collecting shadowy gems won\'t be enough. My work will require entire clusters. Gather them from my father\'s minions...' WHERE `word_id` = 191572; -- locales_quest - details : entry=30116
UPDATE `trans_words` SET `content_loc10`='Dock Workers Interrogated' WHERE `word_id` = 183085; -- locales_quest - ObjectiveText1 : entry=26997
UPDATE `trans_words` SET `content_loc10`='Doctor $N, I presume. It is a pleasure to see you again.$B$BI have some wonderful news for you! Doctor Gregory Victor, chief physician of Horde Trauma has made a personal request for you to join him at Hammerfall. This could be the opportunity of a lifetime! I would give anything to be given a chance to study under the great Doctor Gregory Victor! Do not squander this opportunity!' WHERE `word_id` = 141554; -- locales_quest - details : entry=6623
UPDATE `trans_words` SET `content_loc10`='Doctor $N, I presume. It is a pleasure to see you.$B$BI have some wonderful news for you! Gustaf VanHowzen, chief physician of Alliance Trauma has made a personal request for you to join him at Theramore. This could be the opportunity of a lifetime! I would give anything to be given a chance to study under the great doctor, Gustaf VanHowzen! Do not squander this opportunity, doctor!' WHERE `word_id` = 141560; -- locales_quest - details : entry=6625
UPDATE `trans_words` SET `content_loc10`='Doctor $N, welcome to Alliance Trauma.' WHERE `word_id` = 141558; -- locales_quest - offerrewardtext : entry=6624
UPDATE `trans_words` SET `content_loc10`='Doctor $N, welcome to Horde Trauma.' WHERE `word_id` = 141550; -- locales_quest - offerrewardtext : entry=6622
UPDATE `trans_words` SET `content_loc10`='Doctor Draxlegauge in Faldir\'s Cove wants you to collect 10 Elven Gems and return the Goggles of Gem Hunting once you are done.' WHERE `word_id` = 132988; -- locales_quest - objectives : entry=26051
UPDATE `trans_words` SET `content_loc10`='Doctor Sintar Malefious at Agmar\'s Hammer in the Dragonblight wants you to collect 1 Ruby Lilac.' WHERE `word_id` = 158543; -- locales_quest - objectives : entry=12102
UPDATE `trans_words` SET `content_loc10`='Doctor Theolen Krastinov is responsible for the deaths of thousands. His nickname, The Butcher, is well earned for the atrocities he takes joy in executing. He must be punished, justice must be meted out.$B$BFind him and exact upon him the agony he has inflicted upon countless innocents, including me and my husband. Once he is destroyed, burn our remains. Turn them to ashes, $N. Release our grieving souls.' WHERE `word_id` = 183627; -- locales_quest - details : entry=27146
UPDATE `trans_words` SET `content_loc10`='Doctor Venkman vas vone of my greatest researchers, until he had to be put out of my misery.$B$BHe did leave me vizh vone of his greatest accomplishments, zhough. Against zhe properly attuned supernatural adversary, zhis veapon vill siphon zhe target\'s essence.$B$BIt is of key importance in zhe ritual I vill be attemptink.$B$BVhere do you come in, you ask? Simple. You have zhe priviledge of collecting zhe material.$B$BZhe veapon is calibrated to vork on zhe Furious Specters in zhe temple to zhe east.' WHERE `word_id` = 186321; -- locales_quest - details : entry=27943
UPDATE `trans_words` SET `content_loc10`='Doctor Vomisa, Ph.T. at your service. Here, take this controller. I want you to activate it and give my newly-invented Scrap Reaver X6000 a spin.$B$BJust stay nearby!  The controller is tied to my console here, and if you get too far away, the robot will cease to function.$B$BTry out everything... I\'ll be watching and calibrating its servos based upon your test run.' WHERE `word_id` = 150268; -- locales_quest - details : entry=10248
UPDATE `trans_words` SET `content_loc10`='Does everything down here only come in jumbo size? Oooh! That\'s a thought. Maybe there are some hunky sea goblins around here somewhere. Thanks, by the way.' WHERE `word_id` = 177221; -- locales_quest - offerrewardtext : entry=25360
UPDATE `trans_words` SET `content_loc10`='Does my appearance startle you? Do you know what I am?' WHERE `word_id` = 149181; -- locales_quest - offerrewardtext : entry=9982
UPDATE `trans_words` SET `content_loc10`='Doesn\'t that smell great? My smoked meats get top dollar, and nobody else provides the exotic flavors I\'ve got out here in the hills. And it\'s efficient; you just do the hunting for a small fee, and my other fine friends drag the beasts back here for skinnin\' and smokin\'!$B$BI\'ve got the market cornered on Frostsaber meat right now. Absolutely delicious stuff, makes great sausages. Head out and hunt those cats just west of here, and we\'ll call that a start!' WHERE `word_id` = 188891; -- locales_quest - details : entry=28640
UPDATE `trans_words` SET `content_loc10`='Dokin and Laha have been hard at work helping celebrants learn about the traditional Pilgrim\'s Bounty feast and how to make dishes out of all the ingredients we harvest at this time of year. I\'ve been trying to keep the tables stocked with as many of the dishes as I can, but we\'re running low on pumpkin pie.$B$BWould you be able to get some for us? If you want to make the pies yourself, you\'ll need to buy ripe Tirisfal pumpkins from the Pilgrim\'s Bounty vendor outside the Undercity.' WHERE `word_id` = 164894; -- locales_quest - details : entry=14060
UPDATE `trans_words` SET `content_loc10`='Don Carlos has inadvertently challenged you to defeat his younger self in Old Hillsbrad. Afterwards, bring Don Carlos\' Hat to him in Tanaris as proof.' WHERE `word_id` = 154807; -- locales_quest - objectives : entry=12513
UPDATE `trans_words` SET `content_loc10`='Don Julio\'s Bonescythe armor pattern requires bone fragments - a lot of bone fragments. While those crazy enough to venture into Naxxramas provide me with enough of the core materials to make the armor, I\'m always looking for more Scourge bone fragments.$B$BSo what do you think? Interested in getting your hands dirty and destroying some Scourge at the same time? It\'s a win-win situation.' WHERE `word_id` = 145057; -- locales_quest - details : entry=9126
UPDATE `trans_words` SET `content_loc10`='Don the Pirate Disguise and speak to Handsome Terry inside Scalawag point.' WHERE `word_id` = 171618; -- locales_quest - objectives : entry=11462
UPDATE `trans_words` SET `content_loc10`='Don\' worry, Zen\'Taji\'s not in any trouble. He just been studyin\' what happens when the river overflows.$B$BYa see the big tall birds that stand on the riverbank?  Zen\'Taji thinks they\'re in trouble. The earthquake and the flood pushed the plainstriders over to this side of the water, but they can\'t fly back, and they\'re too scared to swim.$B$BThey\'ll die if they stay here. Zen\'Taji doesn\'t like violence, but maybe YOU can attack them and scare them over to the other side. Yes?' WHERE `word_id` = 176686; -- locales_quest - details : entry=25194
UPDATE `trans_words` SET `content_loc10`='Don\'t accept this assignment if you value your life. You see that gigantic power core jutting out of the mountain side over yonder? Whoever takes on this burden will need to fight their way through that mountain, battling an army of Sunhawks while protecting me as I rig the core up for demolition. Sironas the eredar is somewhere up there as well.$B$BI won\'t think less of you if you just walk away, $N.$B$BBut maybe you\'re the one - the one to destroy the Vector Coil and take down Sironas. Well, are you?' WHERE `word_id` = 148249; -- locales_quest - details : entry=9759
UPDATE `trans_words` SET `content_loc10`='Don\'t be looking!  I\'m not wearin\' me pants!' WHERE `word_id` = 187453; -- locales_quest - offerrewardtext : entry=28233
UPDATE `trans_words` SET `content_loc10`='Don\'t do it, $N. The people that sent you here.... you shouldn\'t trust them.' WHERE `word_id` = 159434; -- locales_quest - offerrewardtext : entry=12300
UPDATE `trans_words` SET `content_loc10`='Don\'t fret, I serve no master, $R. Within these halls lies a book called the Compendium of the Fallen. It holds vast amounts of research that the Scarlet Crusade has done on my kind over the years.$B$BSimply put, I\'d like you to retrieve it and bring it back to me. No questions asked.' WHERE `word_id` = 183064; -- locales_quest - details : entry=26993
UPDATE `trans_words` SET `content_loc10`='Don\'t get ahead of yourself now. Just remember who taught you everything you know. And now let\'s see if we can get out of this city with our skins attached.' WHERE `word_id` = 173770; -- locales_quest - offerrewardtext : entry=14272
UPDATE `trans_words` SET `content_loc10`='Don\'t get me wrong, $N, I\'m glad that you agreed to help with the mines, but for every sapper you killed, I swear two more appeared.$B$BI\'ve been giving Watch Commander Krunk an earful, but he\'s still refusing to send me any help. He keeps muttering something under his breath about helboars. If I wasn\'t so sure he\'d hit me, I\'d tell him this is no time to be thinking about ribs!$B$BAnyway, it looks like there\'s someone down there deep in the mines directing this whole thing. Find him and kill him!' WHERE `word_id` = 149642; -- locales_quest - details : entry=10100
UPDATE `trans_words` SET `content_loc10`='Don\'t get me wrong... I\'m cheerful on the outside, but inside I\'m just terribly torn to pieces. All of my friends and employees are dead.$B$BCould you do me a favor? Would you swim down there and attach the tug\'s tow hook to my dead employees? I\'ll reel them in.' WHERE `word_id` = 186720; -- locales_quest - details : entry=28051
UPDATE `trans_words` SET `content_loc10`='Don\'t go thinking that was too easy. Far greater dangers lurk deeper in the woods.' WHERE `word_id` = 181720; -- locales_quest - offerrewardtext : entry=26618
UPDATE `trans_words` SET `content_loc10`='Don\'t hurt yourself when applying the enchantment, $R.' WHERE `word_id` = 142082; -- locales_quest - offerrewardtext : entry=7484
UPDATE `trans_words` SET `content_loc10`='Don\'t just stand around, when there is so much to be done! Must I instruct everyone on each detail?' WHERE `word_id` = 173718; -- locales_quest - offerrewardtext : entry=14260
UPDATE `trans_words` SET `content_loc10`='Don\'t just stand there! Give me the shark and I\'ll declare you the winner!' WHERE `word_id` = 165185; -- locales_quest - offerrewardtext : entry=24803
UPDATE `trans_words` SET `content_loc10`='Don\'t let Duglas fool you, the Mullans have been itchin\' to take wing again, and if there\'s anyone we\'d do it for, it\'s Firebeard.$B$BWe left our gryphons in the Highland Forest to the south to hunt and to get away from the sounds of battle for a bit. They deserved a rest.$B$BIf you want us back in the air soon, you\'d do well to help us bring our gryphons back in.$B$BTake this piece of charred highland birch. We use it during training - as soon as they smell it, they\'ll come straight back to us.' WHERE `word_id` = 185855; -- locales_quest - details : entry=27811
UPDATE `trans_words` SET `content_loc10`='Don\'t let her beauty fool you, $C. The shadow huntress, Vosh\'gajin is deadly and deranged.$B$B<Kilram points to the scar on his face.>$B$BAye, she gave me that - a love tap, she called it.$B$BThe time for vengeance has finally come.$B$BYou can find Vosh\'gajin in Blackrock Spire. Slay her and return to me with her snakestone. Do this and I will teach you the secret to crafting Dawn\'s Edge!' WHERE `word_id` = 140259; -- locales_quest - details : entry=5306
UPDATE `trans_words` SET `content_loc10`='Don\'t let Thander and company fool you. They may look like a band of fearsome warriors, but underneath all that steel, they\'re nothing more than a troop of dandies!$B$BAnd they won\'t be seen in public without their hats. They\'re extravagant affairs made from felt and fur, complete with the gaudiest feathers you\'ve ever seen.$B$BThe most desirable feathers come from any of the arakkoa, of course, and my supply is running low. I\'ll gladly pay you if you\'ll collect them for me.' WHERE `word_id` = 149195; -- locales_quest - details : entry=9988
UPDATE `trans_words` SET `content_loc10`='Don\'t let the gray hair fool you, grunt. I\'m still ten times the rider that you are! And don\'t go thinking that this old dog doesn\'t have any tricks up his sleeve.$B$BNow all you gotta do is follow me and try not to get knocked down off your mount. If you can do that, Oldie will admit defeat.$B$BWe\'ll lift off as soon as you\'re ready.' WHERE `word_id` = 273676; -- locales_quest - details : entry=11064
UPDATE `trans_words` SET `content_loc10`='Don\'t let their big eyes fool you, mon! Those saltwater snapjaws be a menace. I can\'t fish for five minutes without getting a broken line from one of those oversized fish vacuums stealing my bait.$B$BDo me and the people of Revantusk Village a service and kill em, mon.$B$BKill the whole lot of em!' WHERE `word_id` = 142504; -- locales_quest - details : entry=26211
UPDATE `trans_words` SET `content_loc10`='Don\'t let your guard down, $R. We\'re under constant assault from the Burning Legion.$B$BFrom their base of Legion Hold to the northwest, the demons rain down a ceaseless stream of infernals. As quickly as we can kill them, the new meteors impact and begin a new wave of attacks.$B$BMy men are ragged and exhausted. I don\'t know how much longer they\'ll hold out. Please, $N, lend your help to our defenses. Take your place on the line and halt the advance of the infernals!' WHERE `word_id` = 151478; -- locales_quest - details : entry=10562
UPDATE `trans_words` SET `content_loc10`='Don\'t listen to Rharen. He\'s as addled as they come. It\'s his fault that the ale got captured!$B$BAnd what\'s more, I figure there\'s a bigger issue here than the ale being stolen. The fact that there\'s a bunch of orcs runnin\' about Dun Algaz after all these years is ridiculous!$B$BTell you what, $C. You head in there and be sure to drive as many orcs out of those ruins as you can. Dun Algaz isn\'t good for much anymore, but I\'ll be damned if we let them just sit in there.' WHERE `word_id` = 176758; -- locales_quest - details : entry=25211
UPDATE `trans_words` SET `content_loc10`='Don\'t look at me!  Leave me alone!' WHERE `word_id` = 173429; -- locales_quest - offerrewardtext : entry=14159
UPDATE `trans_words` SET `content_loc10`='Don\'t mind the thundering echoes off the mountains\' walls. The goblins and gnomes are out among the Flats racing one another in atrocities created by what they call science. There are bigger threats here in Thousand Needles, one of which killed more than half my war party.$B$BBut we remain here until we hear word from Belgrom in Orgrimmar. Until then, we hold our position here, and stay vigilant.' WHERE `word_id` = 134948; -- locales_quest - offerrewardtext : entry=1146
UPDATE `trans_words` SET `content_loc10`='Don\'t take the safety of this village for granted. We\'re under siege by the Scourge on the east and the Wretched to the west.$B$BRanger Sareyn keeps our borders safe from the undead that pour in from the Dead Scar. Follow the road eastwards out of town and see if you can lend her a hand.' WHERE `word_id` = 146726; -- locales_quest - details : entry=9358
UPDATE `trans_words` SET `content_loc10`='Don\'t worry about me, $C. I\'ve uncovered the Twilight\'s Hammer plot. They\'ve been stealing and stockpiling explosives coming into Stormwind harbor. Somehow, they\'ve gotten access to the catacombs underneath the Cathedral of Light. I\'ve heard talk of someone called "The Black Bishop."$B$BThere\'s no time to warn the guard, $N! You\'ve got just minutes to get into the catacombs and disarm that bomb. Go! Now! Or THOUSANDS of PEOPLE will DIE!' WHERE `word_id` = 183456; -- locales_quest - details : entry=27092
UPDATE `trans_words` SET `content_loc10`='Don\'t worry about the chamber, my boys will check it out! You have more important things to do!' WHERE `word_id` = 185352; -- locales_quest - offerrewardtext : entry=27672
UPDATE `trans_words` SET `content_loc10`='Don\'t worry about this dragon, $N. We\'ve got plans for it...$B$BDeeper in this mine is a band of crazed Murkblood. After the dragon broke out, they were cut off from the exit. Somehow, after a mere 2 days of isolation, they\'ve lost all sense of decency.$B$BThey\'ve resorted to cannibalism and the promotion of mayhem. We don\'t need that kind of madness in this place. Find \'em and kill \'em. All of \'em.' WHERE `word_id` = 153605; -- locales_quest - details : entry=11083
UPDATE `trans_words` SET `content_loc10`='Don\'t worry, $N; this is all going to lead to something big! HUGE! You\'re just going to have to trust me for now and do as I ask of you.$B$BWe need to get the mechanism mentioned in the manual for the next step of the plan. I have a strong suspicion that you\'ll find one on one of those vrykul that operate the harpoon guns in Wyrmskull Village. You\'ll find them on the east side of the village, on the docks by the longhouses.' WHERE `word_id` = 156566; -- locales_quest - details : entry=11426
UPDATE `trans_words` SET `content_loc10`='Don\'t worry, the feeling of being zapped won\'t stay with you for more than a few minutes. All in all, it\'s not a bad way to get where you\'re going. That parachute system needs some work, though. Very late deployment, indeed. Sometimes, too late. Anyway, we have a mission to carry out.' WHERE `word_id` = 178905; -- locales_quest - offerrewardtext : entry=25839
UPDATE `trans_words` SET `content_loc10`='Donathan on Amber Ledge has tasked you with using the Beryl Shield Detonator to bring down the shield at Beryl Point. You are then to defeat Salrand and collect the key she holds.' WHERE `word_id` = 157298; -- locales_quest - objectives : entry=11671
UPDATE `trans_words` SET `content_loc10`='Donathan ordered you to offer your assistance to Librarian Normantis in the mage tower on Amber Ledge.' WHERE `word_id` = 157196; -- locales_quest - objectives : entry=11646
UPDATE `trans_words` SET `content_loc10`='Donathan wants you to speak to Surristrasz on Amber Ledge.' WHERE `word_id` = 157335; -- locales_quest - objectives : entry=11679
UPDATE `trans_words` SET `content_loc10`='Donathan wants you to use the Arcane Binder on a wounded Beryl Sorcerer at Beryl Point and return to Amber Ledge with him.' WHERE `word_id` = 156922; -- locales_quest - objectives : entry=11590
UPDATE `trans_words` SET `content_loc10`='Donnelly\'s belly! That\'s more like it. Good to not be dyin\' of the thirst again. Here, have some. Good ol\' Eoin\'s never so impolite as ta not share!' WHERE `word_id` = 185243; -- locales_quest - offerrewardtext : entry=27647
UPDATE `trans_words` SET `content_loc10`='Donny at Ivald\'s Ruin in the Howling Fjord wants you to kill 10 Iron Rune Destroyers, 5 Iron Rune Laborers and 2 Iron Rune Sages.' WHERE `word_id` = 156717; -- locales_quest - objectives : entry=11477
UPDATE `trans_words` SET `content_loc10`='Donova Snowden in Winterspring wants you to defeat High Chief Winterfall.' WHERE `word_id` = 139867; -- locales_quest - objectives : entry=5121
UPDATE `trans_words` SET `content_loc10`='Donova Snowden in Winterspring wants you to kill 8 Winterfall Pathfinders, 8 Winterfall Den Watchers, and 8 Winterfall Totemics.' WHERE `word_id` = 139795; -- locales_quest - objectives : entry=5082
UPDATE `trans_words` SET `content_loc10`='Donova Snowden is a kind dwarf who frequents the nearby hot springs. She claims to be studying their magical properties.$B$BShe is a kind person and has good relations with our tribe. As the Winterfall have become more and more aggressive, she has begun researching the cause of their corruption.$B$BI must keep my post here, but I have made a basket of refreshments for her. Please take it to her for me and tell her we await her next visit.' WHERE `word_id` = 188451; -- locales_quest - details : entry=28524
UPDATE `trans_words` SET `content_loc10`='Donova Snowden, dwarf woman, is friend of the Timbermaw.$B$BWe trade firewater.$B$BShe is at Frostfire Hotsprings, to the east, through our cave.$B$BShe needs help to beat up the Winterfall furbolg. Maybe you will help her.' WHERE `word_id` = 189234; -- locales_quest - details : entry=28768
UPDATE `trans_words` SET `content_loc10`='Dontrag can explain it better than me. Basically, we\'re stuck between a rock and a hard place. Can\'t do anything down here due to all of the things that can kill us and can\'t go back to the base due to all of the things that can kill us - you know?$B$BPerhaps if we worked together we might be able to get this mess sorted out. How about you get started by clearing out some of these elementals that have apparently killed everything in the mine, ok?' WHERE `word_id` = 179696; -- locales_quest - details : entry=26046
UPDATE `trans_words` SET `content_loc10`='Doom harkens from the cliffs of Skettis.$B$BMy people, the arakkoa, face a fate shrouded in unspeakable evil. Too often have we abused dark magic for wrongdoing. Through A\'dal I have learned of the Light and of redemption.$B$BTerokk watches his colonies from Skettis through orbs enchanted by the black art. Steal these Eyes from Veil Reskk and Veil Shienor in northern Terokkar. Let me see what Terokk sees. Let me look through the eyes of Skettis.' WHERE `word_id` = 152589; -- locales_quest - details : entry=10847
UPDATE `trans_words` SET `content_loc10`='Doom Lord Kazzak commands the Burning Legion in Outland. While we can\'t get to Kazzak - yet - we can and must get to his lieutenants that command Legion troops from the ground.$B$BThey have stationed dreadlords at the Path of Anguish, east of here. They are the ones responsible for these infernal storms that rain down upon our heads. To take them and their minions out would be a great set back to the Burning Legion.' WHERE `word_id` = 149818; -- locales_quest - details : entry=10142
UPDATE `trans_words` SET `content_loc10`='Doom Lord Kazzak commands the Burning Legion in Outland. While we can\'t get to Kazzak - yet - we can and must get to his lieutenants that command Legion troops from the ground.$B$BThey have stationed dreadlords in Felspark Ravine, east of here. They are responsible for these infernal storms that rain down upon our heads. To take them and their minions out would be a great set back to the Burning Legion.' WHERE `word_id` = 149740; -- locales_quest - details : entry=10123
UPDATE `trans_words` SET `content_loc10`='Doomcryer did nothing to stop the revolt? How dare she! She has been trying to undermine my authority for some time. However, this time will be her last. You must summon her and deal with her personally.$B$BHer anger guards hold the keys that summon her to Forge Camp: Anger. Retrieve the five keys and activate the five Legion obelisks. The obelisks have a short duration, so make sure they are all activated at the same time. Remember, the anger guards carry more keys.' WHERE `word_id` = 152484; -- locales_quest - details : entry=10821
UPDATE `trans_words` SET `content_loc10`='Doomguard Invaders Slain' WHERE `word_id` = 174222; -- locales_quest - ObjectiveText2 : entry=14393
UPDATE `trans_words` SET `content_loc10`='Doomshrooms destroyed' WHERE `word_id` = 181577; -- locales_quest - ObjectiveText1 : entry=26578
UPDATE `trans_words` SET `content_loc10`='Dorain Frosthoof at Taunka\'le Village wants you to use the Windsoul Totem to gather the energy of 10 Steam Ragers.' WHERE `word_id` = 157731; -- locales_quest - objectives : entry=11893
UPDATE `trans_words` SET `content_loc10`='Dorian\'s had me training and feeding the baby drakes he captures, and it has gotten me thinking. I want a pet of my own!$B$BNo, not a juvenile drake. I don\'t want a pet capable of biting my hand off!$B$BHowever, in the Bonefields to the northeast of the camp, beyond the area dominated by the drakes, there\'s a large population of goretalon rocs. The grown ones are beyond hope of domesticating, but if you bring me the eggs from their nests, I can raise them from the time they hatch.' WHERE `word_id` = 160655; -- locales_quest - details : entry=12658
UPDATE `trans_words` SET `content_loc10`='Dorius Escort' WHERE `word_id` = 138001; -- locales_quest - EndText : entry=3367
UPDATE `trans_words` SET `content_loc10`='Dorli\'s filled me in on this crazy trogg-slave operation the kobolds have going, and if you haven\'t talked to her about it yet, I suggest you do.$B$BI\'d like to get to the bottom of this. Literally! Whoever\'s running this show is bound to be at the bottom of the mine, calling the shots, and I want them dealt with.$B$BFind whatever crafty bugger is directing the geomancers and diggers and bring me back their head.' WHERE `word_id` = 182534; -- locales_quest - details : entry=26845
