UPDATE `trans_words` SET `content_loc10`='Drakuru at Granite Springs wants you to use the Dull Carving Knife near his cage and then speak to him.' WHERE `word_id` = 158068; -- locales_quest - objectives : entry=11989
UPDATE `trans_words` SET `content_loc10`='Drakuru in Voltarus wants you to go to the Reliquary of Pain and use the Scepter of Empowerment on a Servant of Drakuru. You are then to use its abilities to defeat Darmuk.' WHERE `word_id` = 160805; -- locales_quest - objectives : entry=12686
UPDATE `trans_words` SET `content_loc10`='Drakuru in Voltarus wants you to speak to Gorebag and take the tour of Zul\'Drak.' WHERE `word_id` = 160683; -- locales_quest - objectives : entry=12663
