UPDATE `trans_words` SET `content_loc10`='Facing the demons of the Burning Legion and the mad cultists that worship them is no small feat, $N. You\'ve shown great dedication and courage. Keep it up and your renown among the Aldor will continue to grow.' WHERE `word_id` = 150632; -- locales_quest - offerrewardtext : entry=10325
UPDATE `trans_words` SET `content_loc10`='Faerie Dragons Rallied' WHERE `word_id` = 177552; -- locales_quest - ObjectiveText1 : entry=25468
