UPDATE `trans_words` SET `content_loc10`='Faulty Valves sealed' WHERE `word_id` = 188663; -- locales_quest - ObjectiveText1 : entry=28584
UPDATE `trans_words` SET `content_loc10`='Featherbeard\'s journal appears to have a large number of recent entries. Leafing back to the beginning of the latest ones, you begin searching for clues about where he might have gone.' WHERE `word_id` = 147130; -- locales_quest - offerrewardtext : entry=9469
