UPDATE `trans_words` SET `content_loc10`='Feed the Fel-Tainted Morsels to the Lost Ones\' captured animals. Then return the leftovers to Cersei Dusksinger at Stonard in the Swamp of Sorrows.' WHERE `word_id` = 147008; -- locales_quest - objectives : entry=9440
