UPDATE `trans_words` SET `content_loc10`='Find 6 Ruuan\'ok Claws and use them at the Ruaan\'ok Oracle Circle to summon a Harbinger of the Raven. Kill it and return its Harbinger\'s Pendant to Timeon at Ruuan Weald.' WHERE `word_id` = 151510; -- locales_quest - objectives : entry=10567
UPDATE `trans_words` SET `content_loc10`='Find 6 Shredder Parts and return to Foreman Razelcraz by the mine northwest of Thrallmar.' WHERE `word_id` = 150211; -- locales_quest - objectives : entry=10236
