UPDATE `trans_words` SET `content_loc10`='Fleshling. Some of your kind skitter among the rocks. Too cowardly to approach, too swift to be crushed.$B$BIf you wish my favor, deal with them. I tire of these games.' WHERE `word_id` = 181583; -- locales_quest - details : entry=26580
