UPDATE `trans_words` SET `content_loc10`='Go to Manaforge Ara and speak to Magister Theledorn.$B$BCompleting quests for the Scryers will cause your Aldor reputation to decrease.' WHERE `word_id` = 150061; -- locales_quest - objectives : entry=10202
UPDATE `trans_words` SET `content_loc10`='Go to Manaforge Duro and retrieve the Sunfury Military Briefing and the Sunfury Arcane Briefing from the Sunfury units stationed there. Return to Exarch Orellis when you\'ve completed this task.$B$BCompleting quests for the Aldor will cause your Scryers reputation level to decrease.' WHERE `word_id` = 150641; -- locales_quest - objectives : entry=10328
