UPDATE `trans_words` SET `content_loc10`='Go to Orgrimmar\'s Drag and speak to a Doomsayer or take a robe from the crate near a Doomsayer to join the cult, then put on your Recruit\'s Robe.' WHERE `word_id` = 171818; -- locales_quest - objectives : entry=25288
