UPDATE `trans_words` SET `content_loc10`='Go to Stone of Inner Binding at Circle of Inner Binding in Arathi Highlands.' WHERE `word_id` = 337677; -- locales_quest - CompletedText : entry=651
UPDATE `trans_words` SET `content_loc10`='Go to Stormwind Harbor and question Snivel Rustrocket about the supplies. Return with any evidence he gives you.' WHERE `word_id` = 165326; -- locales_quest - objectives : entry=24657
