UPDATE `trans_words` SET `content_loc10`='Go to the Battlescar. Scout out the flag marker and kill 10 Desolation Raiders.$B$BCapturing the flag will give all Alliance players in the scar a combat advantage.' WHERE `word_id` = 176275; -- locales_quest - objectives : entry=25081
UPDATE `trans_words` SET `content_loc10`='Go to the Battlescar. Scout out the flag marker and kill 10 Triumph Vanguard soldiers.$B$BCapturing the flag will give all Horde players in the scar a combat advantage.' WHERE `word_id` = 175069; -- locales_quest - objectives : entry=24618
UPDATE `trans_words` SET `content_loc10`='Go to the Black Morass in the Caverns of Time and obtain 10 Essences of Infinity from Rift Lords and Rift Keepers. Bring these along with  5 Elixirs of Major Defense, 5 Elixirs of Mastery and 5 Elixirs of Major Agility to Lorokeem in Shattrath\'s Lower City.$B$B*WARNING!* You can only select one alchemy specialization.' WHERE `word_id` = 152841; -- locales_quest - objectives : entry=10902
UPDATE `trans_words` SET `content_loc10`='Go to the Canal Tailor Shop and bring Rema Schneider the Cloth Request from Harlan Bagley.' WHERE `word_id` = 131549; -- locales_quest - objectives : entry=333
UPDATE `trans_words` SET `content_loc10`='Go to the Caverns of Time in Tanaris and gain access to the Battle of Mount Hyjal. Once inside, defeat Rage Winterchill and bring the Time-Phased Phylactery to Akama in Shadowmoon Valley.' WHERE `word_id` = 153027; -- locales_quest - objectives : entry=10947
UPDATE `trans_words` SET `content_loc10`='Go to the city of Stormwind and speak with Bishop Farthing in the Cathedral of Light. Give him Jitters\' journal and tell him you mean to face Morbent Fel.$B$BAlthough Stormwind has forsaken Darkshire, Farthing is a kind soul and very wise. He may help you on your quest to save us.$B$BYour mission is perilous, but hurry, $N. With each passing hour, the shadows of Duskwood grow ever darker.' WHERE `word_id` = 131272; -- locales_quest - details : entry=269
UPDATE `trans_words` SET `content_loc10`='Go to the Dark Iron Embassy and use the Sturdy Manacles to arrest Ambassador Slaghammer.' WHERE `word_id` = 179968; -- locales_quest - objectives : entry=26118
UPDATE `trans_words` SET `content_loc10`='Go to the Decrepit Ferry.$B$BSearch for the reason the Scourge are there.' WHERE `word_id` = 132007; -- locales_quest - objectives : entry=438
UPDATE `trans_words` SET `content_loc10`='Go to the docks of Ratchet in the Barrens.' WHERE `word_id` = 133980; -- locales_quest - EndText : entry=910
UPDATE `trans_words` SET `content_loc10`='Go to the front gates of Orgrimmar, read the Warchief\'s Proclamation and search 5 Orgrimmar Citizens. Keep anything suspicious that you find.' WHERE `word_id` = 171986; -- locales_quest - objectives : entry=27801
UPDATE `trans_words` SET `content_loc10`='Go to the front gates of Stormwind, read King Wrynn\'s Proclamation and search 5 Stormwind Citizens. Keep anything suspicious that you find.' WHERE `word_id` = 171952; -- locales_quest - objectives : entry=27741
UPDATE `trans_words` SET `content_loc10`='Go to the Fusion Core on top of the M.A.C. Diver in Uldum.' WHERE `word_id` = 337678; -- locales_quest - CompletedText : entry=27778
