UPDATE `trans_words` SET `content_loc10`='Go to the mine in Farshire, obtain the Cart Release Key from Captain Jacobs and use it to release the ore cart. Return to Gerald Green in Farshire when you\'ve completed this task.' WHERE `word_id` = 157794; -- locales_quest - objectives : entry=11904
