UPDATE `trans_words` SET `content_loc10`='Go to the Neferset Prison Camp and find the whereabouts of Tahet.' WHERE `word_id` = 185472; -- locales_quest - objectives : entry=27707
UPDATE `trans_words` SET `content_loc10`='Go to the new Twilight Camp south of the Blackfathom Deeps entrance on the Zoram Strand of Ashenvale and retrieve Twilight Correspondence from the cultists, then call upon the Earthen Ring Guide using the Totemic Beacon.' WHERE `word_id` = 154692; -- locales_quest - objectives : entry=11886
