UPDATE `trans_words` SET `content_loc10`='Go to the Royal Library in Stormwind Keep and speak with Milton Sheaf. He can find for you the book on metallurgy that Brother Kristoff needs for his speech.' WHERE `word_id` = 131592; -- locales_quest - objectives : entry=343
UPDATE `trans_words` SET `content_loc10`='Go to the Shards of Myzrael, summon her and defeat her.$B$BGather her Eldritch Shackles and bind them to the Shards of Myzrael.' WHERE `word_id` = 132947; -- locales_quest - objectives : entry=656
UPDATE `trans_words` SET `content_loc10`='Go to the Silver Stream Mine and collect 4 loads of Miners\' Gear.$B$BReturn to Mountaineer Stormpike.' WHERE `word_id` = 131440; -- locales_quest - objectives : entry=307
