UPDATE `trans_words` SET `content_loc10`='Go to the Temple City of En\'kilah and find the teleportation orb beneath the floating Scourge citadel of Naxxanar. Use it to reach the top and help Thassarian there.' WHERE `word_id` = 158184; -- locales_quest - objectives : entry=12019
UPDATE `trans_words` SET `content_loc10`='Go to the top of the Atam\'al Terrace in Shadowmoon Valley and obtain the Heart of Fury. Return to Akama at the Warden\'s Cage in Shadowmoon Valley when you\'ve completed this task.' WHERE `word_id` = 152045; -- locales_quest - objectives : entry=10707
