UPDATE `trans_words` SET `content_loc10`='Go to the tower the slave spoke of. You should find it on the northeastern end of the camp.$B$BIf we can act fast enough we might be able to eavesdrop on the forgemaster\'s meeting.' WHERE `word_id` = 180454; -- locales_quest - details : entry=26260
UPDATE `trans_words` SET `content_loc10`='Go to the town hall building in Farshire and ring the bell inside of it.' WHERE `word_id` = 157989; -- locales_quest - objectives : entry=11965
