UPDATE `trans_words` SET `content_loc10`='Go to the Writhing Haunt in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron. You must have the Empty Writhing Haunt Bottle with you to secure a sample of the poisons used inside the cauldron.' WHERE `word_id` = 140105; -- locales_quest - objectives : entry=5222
UPDATE `trans_words` SET `content_loc10`='Go to the zeppelin tower outside Orgrimmar and question Snivel Rustrocket about the supplies. Return with any evidence he gives you.' WHERE `word_id` = 165263; -- locales_quest - objectives : entry=24576
