UPDATE `trans_words` SET `content_loc10`='Greymane wants to save Crowley?  Has he gone mad?' WHERE `word_id` = 173424; -- locales_quest - offerrewardtext : entry=14157
UPDATE `trans_words` SET `content_loc10`='Greymane\'s right. These beasts do not give a damn about our politics. Gilneas needs to stand together.' WHERE `word_id` = 189413; -- locales_quest - offerrewardtext : entry=28850
UPDATE `trans_words` SET `content_loc10`='Greymist Murloc Home Built' WHERE `word_id` = 172782; -- locales_quest - ObjectiveText1 : entry=13910
