UPDATE `trans_words` SET `content_loc10`='Help Donnelly find Beak in Dunwald Hovel.' WHERE `word_id` = 185235; -- locales_quest - objectives : entry=27646
UPDATE `trans_words` SET `content_loc10`='Help Dorius get back to Ironforge.' WHERE `word_id` = 270838; -- locales_quest - objectives : entry=3367
UPDATE `trans_words` SET `content_loc10`='Help Elderlimb, Thisalee Crow, Tholo Whitehoof and Anren Shadowseeker escape the flames.' WHERE `word_id` = 190399; -- locales_quest - objectives : entry=29197
UPDATE `trans_words` SET `content_loc10`='Help Emily and Mr. Floppy get back to the Westfall Brigade Encampment, then speak to Squire Walter.' WHERE `word_id` = 158196; -- locales_quest - objectives : entry=12027
