UPDATE `trans_words` SET `content_loc10`='Help Getry defeat Varidus the Flenser at Warsong Farms.$B$BReport to Garrosh Hellscream should you succeed.' WHERE `word_id` = 274110; -- locales_quest - details : entry=11705
