UPDATE `trans_words` SET `content_loc10`='Help Malukaz Summon the Wolf Spirit' WHERE `word_id` = 152348; -- locales_quest - ObjectiveText2 : entry=10791
UPDATE `trans_words` SET `content_loc10`='Help Marshal Windsor get his gear back and free his friends. Return to Marshal Maxwell if you succeed.' WHERE `word_id` = 139062; -- locales_quest - objectives : entry=4322
UPDATE `trans_words` SET `content_loc10`='Help Maximillian of Northshire kill the Devilsaur Queen. If you become separated from Maximillian, meet him at Golakka Hot Springs in Un\'Goro Crater.' WHERE `word_id` = 175334; -- locales_quest - objectives : entry=24707
UPDATE `trans_words` SET `content_loc10`='Help Maximillian of Northshire slay 15 "Dragons".' WHERE `word_id` = 175318; -- locales_quest - objectives : entry=24704
UPDATE `trans_words` SET `content_loc10`='Help me make some Westfall Stew!  Come back with the following ingredients: $B $B 3 Stringy Vulture Meat $B 3 Goretusk Snouts $B 3 Murloc Eyes $B 3 Okra' WHERE `word_id` = 130297; -- locales_quest - details : entry=38
UPDATE `trans_words` SET `content_loc10`='Help me, $C! Piggy men come burn stables - fire! Fire!$B$B<Dorak wails incoherently before you can settle him down.>$B$BWolves still chained inside. Someone\'s got to save the wee wolves!' WHERE `word_id` = 172667; -- locales_quest - details : entry=13878
UPDATE `trans_words` SET `content_loc10`='Help me, $N! The Bristlelimb captured me and are planning to sacrifice me to their foul gods!$B$BHigh Chief Bristlelimb holds the key that opens the cage. To force him to appear, you must slaughter the evil Bristlelimb furbolgs that inhabit the enclave, just two camps to the west of this camp. If you kill enough of them, he will surely come for vengeance! When he shows up, kill him and get the key!$B$BMy father will richly reward you if you can save me!' WHERE `word_id` = 147866; -- locales_quest - details : entry=9667
UPDATE `trans_words` SET `content_loc10`='Help me, stranger. I must... reach Tranquillien... I cannot fail.$B$B<The blood elf falls back into unconsciousness as his eyes go blank.>' WHERE `word_id` = 146300; -- locales_quest - offerrewardtext : entry=9144
UPDATE `trans_words` SET `content_loc10`='Help Naralex seal the Nightmare Scar.' WHERE `word_id` = 175031; -- locales_quest - objectives : entry=24601
UPDATE `trans_words` SET `content_loc10`='Help out a fellow swabbie?$B$BKeelhaul asked me to gather up some cannonballs at the bottom of the ocean. Let me tell you why this doesn\'t work for me.$B$B- One: I have tiny arms. Look at them!  Do you really think I can pick up a cannonball, even underwater?$B$B- Two: I have a weak respiratory system. I start to white out after holding my breath for more than ten seconds.$B$B- Three: There are sharks.$B$BYou gotta help me, $N!  I\'ve been demoted as far as I can... I don\'t want to see what comes next!' WHERE `word_id` = 181788; -- locales_quest - details : entry=26635
UPDATE `trans_words` SET `content_loc10`='Help Patches kill Doctor Sabnok' WHERE `word_id` = 162818; -- locales_quest - ObjectiveText2 : entry=13152
UPDATE `trans_words` SET `content_loc10`='Help Pilot Vic complete the Reconnaissance Flight.' WHERE `word_id` = 160725; -- locales_quest - objectives : entry=12671
UPDATE `trans_words` SET `content_loc10`='Help Raggaran' WHERE `word_id` = 176660; -- locales_quest - ObjectiveText2 : entry=25188
