UPDATE `trans_words` SET `content_loc10`='Help Salhet slay 8 Bloodsnarl Hyenas.' WHERE `word_id` = 187345; -- locales_quest - objectives : entry=28210
UPDATE `trans_words` SET `content_loc10`='Help Sergeant Flinthammer and his mountaineers defend Amberstill Ranch from Frostmane Raiders.' WHERE `word_id` = 179318; -- locales_quest - objectives : entry=25932
