UPDATE `trans_words` SET `content_loc10`='Huntsman Leopold at Light\'s Hope Chapel in the Eastern Plaguelands will make a Cryptstalker Girdle if you bring him the following: 1 Desecrated Girdle, 8 Wartorn Chain Scraps, 1 Arcanite Bar and 3 Nexus Crystals.' WHERE `word_id` = 272241; -- locales_quest - objectives : entry=9060
