UPDATE `trans_words` SET `content_loc10`='Jump on Aggra\'s Wyvern and fly into the breach at the Maelstrom. Once you\'re on the other side, speak to Maruut Stonebinder.' WHERE `word_id` = 183560; -- locales_quest - objectives : entry=27123
UPDATE `trans_words` SET `content_loc10`='Jump on Stormbeak and watch Mor\'norokk\'s interrogation.' WHERE `word_id` = 180427; -- locales_quest - objectives : entry=26254
UPDATE `trans_words` SET `content_loc10`='Just a moment ago a messenger was looking for you, $N. I believe she was sent by the druid trainer Gart. If this note is from Gart, I wouldn\'t take long in reading its contents.' WHERE `word_id` = 270749; -- locales_quest - details : entry=3094
UPDATE `trans_words` SET `content_loc10`='Just a moment ago a messenger was looking for you, $N. I believe she was sent by the hunter trainer Lanka. If this note is from Lanka, I wouldn\'t take long in reading it\'s contents.' WHERE `word_id` = 270740; -- locales_quest - details : entry=3092
