UPDATE `trans_words` SET `content_loc10`='Kaldon sent you? Very well, let\'s see what we can do for you.' WHERE `word_id` = 144368; -- locales_quest - offerrewardtext : entry=8800
UPDATE `trans_words` SET `content_loc10`='Kalecgos has asked you to defeat Kael\'thas in Magisters\' Terrace. You are to take Kael\'s head and report back to Larethor at the Shattered Sun Staging Area.' WHERE `word_id` = 154399; -- locales_quest - objectives : entry=11492
