UPDATE `trans_words` SET `content_loc10`='klajsdklajlsd' WHERE `word_id` = 158170; -- locales_quest - details : entry=12015
UPDATE `trans_words` SET `content_loc10`='Klatu in Honor Hold wants you to use the Anchorite Relic at Gor\'gaz Outpost southwest of Honor Hold, slay Shattered Hand Berserkers near the relic, and then slay 10 released Fel Spirits to avenge Colonel Jules.' WHERE `word_id` = 152868; -- locales_quest - objectives : entry=10909
UPDATE `trans_words` SET `content_loc10`='Kneel, champion. I place this helm upon your head to complete your terrifying visage. Any that dare look upon your dark countenance will know that death comes. Let none stand so boldly against your king so as to face your merciless wrath, $N.$B$BThere remains only one final task...$B$B<The Lich King looks west.>$B$BLight\'s Hope Chapel.' WHERE `word_id` = 161197; -- locales_quest - offerrewardtext : entry=12779
