UPDATE `trans_words` SET `content_loc10`='Kul the Reckless rescued' WHERE `word_id` = 164721; -- locales_quest - ObjectiveText1 : entry=14096
UPDATE `trans_words` SET `content_loc10`='Kul will live to embarrass himself again. That\'s far from the first time someone\'s had to save Kul from himself. With examples like him, it\'s no wonder most of the aspirants are taking up the habits of the Silver Covenant.' WHERE `word_id` = 164774; -- locales_quest - offerrewardtext : entry=14142
