UPDATE `trans_words` SET `content_loc10`='Learn Seal of Righteousness and Judgement from Aurelon. Apply Seal of Righteousness, find a Training Dummy on the northwest side of the Crash Site and use Judgement.' WHERE `word_id` = 182966; -- locales_quest - objectives : entry=26966
UPDATE `trans_words` SET `content_loc10`='Learn Seal of Righteousness and Judgement from Sunwalker Helaku. Locate a Training Dummy in Camp Narache and practice using Judgement.' WHERE `word_id` = 183188; -- locales_quest - objectives : entry=27023
UPDATE `trans_words` SET `content_loc10`='Learn Seal of Righteousness and Judgment from Bromos Grummner. After casting Seal of Righteousness on yourself, use Judgment on one of the Training Dummies at the entrance to Anvilmar.' WHERE `word_id` = 174881; -- locales_quest - objectives : entry=24528
UPDATE `trans_words` SET `content_loc10`='Learn Spell: Judgement' WHERE `word_id` = 174884; -- locales_quest - ObjectiveText2 : entry=24528
UPDATE `trans_words` SET `content_loc10`='Learn Steady Shot from Ayanna Everstride. Look for a Training Dummy southeast of Aldrassil, and practice using Steady Shot 5 times.' WHERE `word_id` = 182883; -- locales_quest - objectives : entry=26947
UPDATE `trans_words` SET `content_loc10`='Learn Steady Shot from Karranisha in the Valley of Trials. Locate a Training Dummy and practice using Steady Shot 5 times.' WHERE `word_id` = 176469; -- locales_quest - objectives : entry=25139
UPDATE `trans_words` SET `content_loc10`='Learn Steady Shot from Keilnei. Find a Training Dummy on the northwest side of the Crash Site and practice using Steady Shot 5 times.' WHERE `word_id` = 182954; -- locales_quest - objectives : entry=26963
UPDATE `trans_words` SET `content_loc10`='Learn Steady Shot from Lanka Farshot. Locate a Training Dummy in Camp Narache and practice using Steady Shot 5 times.' WHERE `word_id` = 183182; -- locales_quest - objectives : entry=27021
UPDATE `trans_words` SET `content_loc10`='Learn Steady Shot from Ranger Sallina. Locate a Training Dummy outside the Sunspire and practice using Steady Shot 5 times.' WHERE `word_id` = 169927; -- locales_quest - objectives : entry=10070
UPDATE `trans_words` SET `content_loc10`='Learn Steady Shot from Thorgas Grimson, then use Steady Shot 5 times on the Training Dummies outside the entrance to Anvilmar.' WHERE `word_id` = 174893; -- locales_quest - objectives : entry=24530
UPDATE `trans_words` SET `content_loc10`='Learn Steady Shot from Xavier the Huntsman in Deathknell, then practice using Steady Shot 5 times on a Training Dummy.' WHERE `word_id` = 175826; -- locales_quest - objectives : entry=24964
UPDATE `trans_words` SET `content_loc10`='Learn Steelfeather\'s Secret' WHERE `word_id` = 156536; -- locales_quest - ObjectiveText1 : entry=11418
UPDATE `trans_words` SET `content_loc10`='Learn the purpose of the Stone Watcher of Norgannon' WHERE `word_id` = 137553; -- locales_quest - EndText : entry=2954
UPDATE `trans_words` SET `content_loc10`='Learn the purpose of the Stone Watcher of Norgannon, and then interact with the Uldum Pedestal in the Tanaris desert.' WHERE `word_id` = 137550; -- locales_quest - objectives : entry=2954
UPDATE `trans_words` SET `content_loc10`='Learn what it means to be Horde.' WHERE `word_id` = 179959; -- locales_quest - objectives : entry=26115
UPDATE `trans_words` SET `content_loc10`='Learn what lore that the stone watcher has to offer' WHERE `word_id` = 136729; -- locales_quest - EndText : entry=2278
UPDATE `trans_words` SET `content_loc10`='Leave Drum inside Barn' WHERE `word_id` = 183012; -- locales_quest - ObjectiveText4 : entry=26978
UPDATE `trans_words` SET `content_loc10`='Leave Drum near Grain Silos' WHERE `word_id` = 183010; -- locales_quest - ObjectiveText2 : entry=26978
UPDATE `trans_words` SET `content_loc10`='Leave Drum near Windmill' WHERE `word_id` = 183009; -- locales_quest - ObjectiveText1 : entry=26978
UPDATE `trans_words` SET `content_loc10`='Leave it to the Dark Irons to work with Ragnaros\' toadies and worse. You can bet that insane Twilight\'s Hammer cult is behind the lot of this!$B$BTime to end their attacks on Ironforge once and for all. Oh, and tell Commander Cragfist what\'s happened here when we return; I\'ll need to work on getting the city and its good people back in order.' WHERE `word_id` = 171907; -- locales_quest - details : entry=27122
UPDATE `trans_words` SET `content_loc10`='Leave?  Now?$B$BWell, if I must, then I must. But will you be a sweetheart and find something for me?$B$BI\'ve lost my favorite book and won\'t leave without it.$B$B<After you explain the gravity of the situation, Grandma Wahl shakes her head condescendingly.>$B$BDear, just find the book will you?' WHERE `word_id` = 174246; -- locales_quest - details : entry=14399
UPDATE `trans_words` SET `content_loc10`='Lebronski Bluffed' WHERE `word_id` = 156757; -- locales_quest - EndText : entry=11491
UPDATE `trans_words` SET `content_loc10`='LeCraft had it you say? That makes sense.$B$BI recognize it from my youthful days as a torturer in the court of King Terenas of fallen Lordaeron. It\'s known as a rod of compulsion.$B$B<The high executor wrings his hands together in evil anticipation of what\'s to come.>$B$BI have an idea for how we can make good use of it!' WHERE `word_id` = 159295; -- locales_quest - offerrewardtext : entry=12271
UPDATE `trans_words` SET `content_loc10`='Led by Admiral Proudmoore, the humans of Kul Tiras encroached on Durotar, violating the Warchief\'s pact made with Jaina Proudmoore in order to defeat Archimonde years ago.$B$BThe human aggression was repelled and Tiragarde Keep fell. But recently, the Admiral\'s reserves, led by Lieutenant Benedict, have retaken the keep and once again pose a threat to our homeland. These humans show no respect for diplomacy.$B$BProve your honor and travel south to Tiragarde Keep to eliminate the human invaders.' WHERE `word_id` = 133497; -- locales_quest - details : entry=784
UPDATE `trans_words` SET `content_loc10`='Left Leg Servos Tested' WHERE `word_id` = 165398; -- locales_quest - ObjectiveText1 : entry=25289
UPDATE `trans_words` SET `content_loc10`='Legassi at the Zeppelin Crash wants you to gather 8 Purified Helboar Meat. To purify the meat, use the Purification Mixture on the Tainted Helboar Meat you gather from Helboars.' WHERE `word_id` = 146739; -- locales_quest - objectives : entry=9361
UPDATE `trans_words` SET `content_loc10`='Legend has it that the chimaerok of the Isle of Dread in Feralas have the most succulent and tender vittles in existence! Now these chimaerok also have a daddy who, with proper preparation, may or may not look like a 500 pound chicken.$B$BHead to the Isle of Dread and kill Lord Lakmaeran and bring me his fresh carcass. That should satisfy the gnome. To satisfy me, you\'ll need to get your hands on some chimaerok tenderloin.$B$BDo this and you\'ll have your 500 pound chicken and a little something extra.' WHERE `word_id` = 272070; -- locales_quest - details : entry=8585
UPDATE `trans_words` SET `content_loc10`='Legends tell of a jewel, hidden deep in the heart of Stranglethorn. We call it the Mind\'s Eye, and it has great powers. If you gain this Eye then, perhaps, we can use it to bring lost Yenniku back from the darkness.$B$BI will consult with the spirits of the jungle to find the Mind\'s Eye. While I do this, you enter the Crystalvein Mine, southeast of here, and gather Pulsing Blue Shards from Ironjaw Basilisks. The shards are rare, but we will need their magic to bend the Mind\'s Eye to our will.' WHERE `word_id` = 132674; -- locales_quest - details : entry=589
UPDATE `trans_words` SET `content_loc10`='Legion Antenna: Fear Destroyed' WHERE `word_id` = 149754; -- locales_quest - ObjectiveText4 : entry=10125
UPDATE `trans_words` SET `content_loc10`='Legion Antenna: Rage Destroyed' WHERE `word_id` = 149752; -- locales_quest - ObjectiveText2 : entry=10125
UPDATE `trans_words` SET `content_loc10`='Legion Antenna: Spite Destroyed' WHERE `word_id` = 149751; -- locales_quest - ObjectiveText1 : entry=10125
UPDATE `trans_words` SET `content_loc10`='Legion Demon archived' WHERE `word_id` = 191536; -- locales_quest - ObjectiveText1 : entry=30104
UPDATE `trans_words` SET `content_loc10`='Legion Gateway Destroyed' WHERE `word_id` = 154461; -- locales_quest - EndText : entry=11516
UPDATE `trans_words` SET `content_loc10`='Legionnaire Nazgrim and many of the other survivors have already made their way to the surface. I\'m sure some are just looking to rid themselves of this place for good, but we still have work to do if we\'re going to stop the naga from invading the plane of water.$B$BFirst, we need to set eyes on the tentacled fiend that destroyed our ships when we first arrived - we don\'t want a repeat of that nightmare.$B$BFiasco left these behind for you. They should speed your trip up a bit.' WHERE `word_id` = 179566; -- locales_quest - details : entry=26006
UPDATE `trans_words` SET `content_loc10`='Legionnaire Nazgrim wants you to slay Lady Naz\'jar.' WHERE `word_id` = 189389; -- locales_quest - objectives : entry=28843
UPDATE `trans_words` SET `content_loc10`='Lemme check the connections... and we\'re set. You do the honors, $N. Push it. Push the button!$B$BPush the button, $N!$B$BAfter the fireworks, go tell Kroum back at Valormok that his skies are clear.$B$BPush the button!' WHERE `word_id` = 174485; -- locales_quest - details : entry=14477
UPDATE `trans_words` SET `content_loc10`='Leokk has brought to us the head from one of the black dragons at Dragon\'s End. With this, we will be able to infuriate Goc, the gronn that captured him, and lure him into battle.' WHERE `word_id` = 152133; -- locales_quest - offerrewardtext : entry=10724
UPDATE `trans_words` SET `content_loc10`='Leoroxx has beseeched you to retrieve the Collection of Souls and return them to Spiritcaller Dohgar at Mok\'Nathal Village in the Blade\'s Edge Mountains.' WHERE `word_id` = 152692; -- locales_quest - objectives : entry=10867
UPDATE `trans_words` SET `content_loc10`='Leoroxx has challenged you to slay Dreadwing. Return to him at Mok\'Nathal Village once you have managed to kill her.' WHERE `word_id` = 152580; -- locales_quest - objectives : entry=10845
UPDATE `trans_words` SET `content_loc10`='Leryssa... is looking for me?  You must help me, $N. We must finish this before she gets hurt.' WHERE `word_id` = 158476; -- locales_quest - offerrewardtext : entry=12088
UPDATE `trans_words` SET `content_loc10`='Less gilblins is good.$B$BI\'m glad that they\'re so primitive. I don\'t think I\'d want to be dealing with a race of aquatic tech-freaks right now.' WHERE `word_id` = 179441; -- locales_quest - offerrewardtext : entry=25969
UPDATE `trans_words` SET `content_loc10`='Less gill goblins is good! I\'m glad that they\'re so primitive. I don\'t think I\'d want to be dealing with a race of aquatic tech-freaks right now. Not at all.' WHERE `word_id` = 179154; -- locales_quest - offerrewardtext : entry=25894
UPDATE `trans_words` SET `content_loc10`='Lesser Infernals Destroyed' WHERE `word_id` = 174045; -- locales_quest - ObjectiveText1 : entry=14342
UPDATE `trans_words` SET `content_loc10`='Lesson one. Aside from your sword and shield, what\'s the most important tool you have in your arsenal?$B$B<Thran awaits your response.>$B$BOh never mind, I\'ll answer it for you. It\'s your mobility. One of the strengths of the warrior is the ability to get around the battlefield quickly. Here, $N, I\'ll train you to use your legs to your advantage.' WHERE `word_id` = 174896; -- locales_quest - details : entry=24531
UPDATE `trans_words` SET `content_loc10`='Lestharia Vashj statue' WHERE `word_id` = 177922; -- locales_quest - ObjectiveText1 : entry=25581
UPDATE `trans_words` SET `content_loc10`='Let Captain Tread Sparknozzle know you ejected safely.' WHERE `word_id` = 337710; -- locales_quest - CompletedText : entry=25285
UPDATE `trans_words` SET `content_loc10`='Let Commander Ebonlocke know immediately that the handwriting matched, $N!  Her suspicions were correct!' WHERE `word_id` = 130532; -- locales_quest - details : entry=97
UPDATE `trans_words` SET `content_loc10`='Let it be known that Zorus does have a sense of humor.$B$BEnough small talk. Don the Spectrecles so that you are able to see the Shadowmoon orc spirits that wander this stronghold. Do not be frightened as we are truly the invaders here. Alas, they must be destroyed, for their time has long since passed.$B$BDestroy the Shadowmoon harbingers infesting Wildhammer Stronghold and return to me.' WHERE `word_id` = 151831; -- locales_quest - details : entry=10643
UPDATE `trans_words` SET `content_loc10`='Let Jarkal borrow the necklace. In exchange, he will translate the journal for you.' WHERE `word_id` = 136772; -- locales_quest - objectives : entry=2338
UPDATE `trans_words` SET `content_loc10`='Let Kadrak know of the success we have had here holding off the night elves. Our plans are going well.' WHERE `word_id` = 141415; -- locales_quest - offerrewardtext : entry=6547
UPDATE `trans_words` SET `content_loc10`='Let Karynaku return you to Mordenai in the Netherwing Fields.' WHERE `word_id` = 152707; -- locales_quest - objectives : entry=10870
UPDATE `trans_words` SET `content_loc10`='Let me be the first to welcome you aboard, Junior Technician 3rd Grade $N!$B$BWe\'re building my masterpiece out here - the X-52 Nether-Rocket!$B$BBut first we need to get all of the parts and fuel for it. That\'s where you come in.$B$BTo start, I need crystals - LOTS of crystals - for the rocket\'s Etherlithium Engine Matrix. The draenei had crystals coming out of their ears!$B$BSo head north to the Ruins of Enkaat and get them for me!  Nevermind all of the draenei ghosts.' WHERE `word_id` = 149987; -- locales_quest - details : entry=10186
UPDATE `trans_words` SET `content_loc10`='Let me get this straight -- a $R I don\'t know brings me a cask of the finest booze in this miserable forest. Ok, then, what are you after?' WHERE `word_id` = 158104; -- locales_quest - offerrewardtext : entry=11998
UPDATE `trans_words` SET `content_loc10`='Let me get you up to speed, $N.$B$BUndercity is a war-zone. Putress\' apothecaries and Varimathras\' demons have seized control. They\'ve taken a defensive position inside and are using that damned blight against our troops.' WHERE `word_id` = 163310; -- locales_quest - offerrewardtext : entry=13266
UPDATE `trans_words` SET `content_loc10`='Let me guess - you didn\'t get whatever world-ending, nefarious deed you were doing done in time. No wait, better still... you dropped it in the sand!  Well, whatever the reason, I do have additional power sources I will sell to you. This time, however, it will cost you ten, YES TEN Wastewander Water Pouches!$B$BTimes are tough all around, $N, and power sources don\'t grow on trees!  Hrm, but what if they did. Maybe we could MAKE a power source tree...' WHERE `word_id` = 133683; -- locales_quest - details : entry=841
UPDATE `trans_words` SET `content_loc10`='Let me have a look at that.$B$BHmm, there doesn\'t appear to be anything special about it. I doubt this is it, though the manner in which you describe the Burning Legion\'s activities at the ruins, it sounds as if they\'re searching for something in particular as well.$B$BLet us hope that it\'s not the crystal that the nexus-prince wants so badly.' WHERE `word_id` = 150344; -- locales_quest - offerrewardtext : entry=10265
UPDATE `trans_words` SET `content_loc10`='Let me live and I\'ll tell you whatever you want to know!' WHERE `word_id` = 148808; -- locales_quest - offerrewardtext : entry=9889
UPDATE `trans_words` SET `content_loc10`='Let me look at those.$B$B<The chronicler examines the artifacts that you have recovered.>$B$BHmph, I\'d say that we\'re lucky you liberated these when you did, $C.$B$BHow very interesting. This artifact here depicts the events of the Sundering. There was a time when Northrend was the far northern portion of Kalimdor.$B$BBut after the Sundering, the land broke off, eventually becoming Northrend.$B$BThis, of course, is why we see Drakkari in the southern continents as well as here.' WHERE `word_id` = 160622; -- locales_quest - offerrewardtext : entry=12650
UPDATE `trans_words` SET `content_loc10`='Let me see if I can find out how this works...' WHERE `word_id` = 151615; -- locales_quest - offerrewardtext : entry=10589
UPDATE `trans_words` SET `content_loc10`='Let me see your hands... Aha!  Your not any better at collecting these wretched things than I am!' WHERE `word_id` = 180325; -- locales_quest - offerrewardtext : entry=26227
UPDATE `trans_words` SET `content_loc10`='Let me see, let me see... flare gun... balloon... no rope. Never any rope. Terribly impractical if you do ask me. Rope should be mandatory.' WHERE `word_id` = 179158; -- locales_quest - offerrewardtext : entry=25895
UPDATE `trans_words` SET `content_loc10`='Let me see... faintly written, among the engraved incantations, is the name of its master!$B$B"Umbranse..."' WHERE `word_id` = 188500; -- locales_quest - offerrewardtext : entry=28537
UPDATE `trans_words` SET `content_loc10`='Let me take a look at those.$B$BYes, I think that these will do nicely; good job, $N. The emitter is rather complex so it may take some time to finish the repairs. I\'ll let you know when it\'s ready.$B$BIn the meantime, you might see if Vindicator Aldar has anything he could use you for.' WHERE `word_id` = 146637; -- locales_quest - offerrewardtext : entry=9305
UPDATE `trans_words` SET `content_loc10`='Let me tell ya somethin\' $C! The bossman simply doesn\'t appreciate the art and craftsmanship that goes into making fine explosives.' WHERE `word_id` = 172847; -- locales_quest - offerrewardtext : entry=13936
UPDATE `trans_words` SET `content_loc10`='Let me tell you a story.$B$BOnce, there was a foolish troll named Zengu. He was tasked to find the sword Trol\'kalar, the legendary blade of the human Trollbane line. He succeeded, and thinking his task done, went to leave Arathi by himself. There he was cut down by the humans, and the sword simply reclaimed.$B$BWe will not be so foolish. Our apothecaries have given us the perfect guide to reobtain Trol\'kalar: the prince who once held it.$B$BHe stands ready to guide you, $N. Speak with him.' WHERE `word_id` = 179631; -- locales_quest - details : entry=26023
UPDATE `trans_words` SET `content_loc10`='Let me tell you more of the task you must complete. The druids in Darnassus use the water of the moonwells of Teldrassil, and their moonwell must be replenished from time to time. Using these specially crafted phials, you can collect the water of the moonwells.$B$BTake this vessel to the moonwell outside of Starbreeze Village to the east, and fill it with some of its waters, then return to me. Pay heed to the lessons of the moonwells, lest we find ourselves furthering our shortcomings.' WHERE `word_id` = 166695; -- locales_quest - details : entry=929
UPDATE `trans_words` SET `content_loc10`='Let me tell you something about Frost Oil: nothing can keep an engine or gears from overheating quite like it.$B$BIts cooling properties are extraordinary, and its longevity as a lubricant without equal. That\'s not all: it also aids in retaining enchantments on magical items.$B$BI need a vial of it to increase the magical capacity of my shackles and make them powerful enough to stop our summoned friend from killing us all.$B$BBro\'kin, a goblin friend of mine, can teach you to make it. He\'s in Alterac.' WHERE `word_id` = 133194; -- locales_quest - details : entry=713
UPDATE `trans_words` SET `content_loc10`='Let me tell you something, mon. When you get put in charge of outfittin\' the armies of the Horde, you go through a lot of hides!$B$BConqueror Krenna, the she-wolf runnin\' this place, she gave me a tight deadline. If I don\'t outfit her whole regiment by week\'s end she\'s gonna have me wrestling bears in the pit.$B$BHelp me out and I\'ll pay you top price. I\'ll be needin\' hides from graymist hunters.$B$BYou\'ll find them all around in pockets to the north, hunting stag. Remember, mon. Top price!' WHERE `word_id` = 158851; -- locales_quest - details : entry=12175
UPDATE `trans_words` SET `content_loc10`='Let me think for a second. The Violet Eye... Medivh\'s Journal... Why yes, it\'s all coming back to me now.$B$BI believe I had the journal you\'re looking for before I started to read these scrolls...$B$BAran... yes, Aran asked me for the book. So nicely too. I just had to give it to him. He\'s Medivh\'s father after all, did you know?' WHERE `word_id` = 147806; -- locales_quest - details : entry=9640
UPDATE `trans_words` SET `content_loc10`='Let me to be frank with you, $N. I\'m interested - nay, concerned with why the Arch Druid in Darnassus is using the name of the Cenarion Circle as well as the Circle\'s resources to procure vast amounts of morrowgrain. I\'m a researcher - curses are my specialty. I\'ve heard that morrowgrain, under the right conditions, exude qualities like other herbs used in primitive curses.$B$BI want to know more, and I ask for your help. Bring me ten morrowgrain, and I will be sure to take care of you.' WHERE `word_id` = 138474; -- locales_quest - details : entry=3791
UPDATE `trans_words` SET `content_loc10`='Let Myranda have a look, $R.$B$BOh yes, these will do nicely.$B$BWith these reagents, Myranda will create for you a medallion that will grant an illusion capable of fooling the black dragonflight\'s gatekeeper.' WHERE `word_id` = 141462; -- locales_quest - offerrewardtext : entry=6569
UPDATE `trans_words` SET `content_loc10`='Let our enemies see that a soldier of rank has struck them down! Fight for the glory of Stormpike!' WHERE `word_id` = 141919; -- locales_quest - offerrewardtext : entry=7168
UPDATE `trans_words` SET `content_loc10`='Let the goblins and all the Horde know we will not have offers of peace and sanctuary abused... most of all not in our new home. I am grateful my people have found allies as bold as you, $N. This reward will represent your bond with our pack. You will always be welcome here.' WHERE `word_id` = 188083; -- locales_quest - offerrewardtext : entry=28389
UPDATE `trans_words` SET `content_loc10`='Let them seek atonement at the end of your munitions.' WHERE `word_id` = 142974; -- locales_quest - offerrewardtext : entry=8147
UPDATE `trans_words` SET `content_loc10`='Let us be clear about one thing, $N: I don\'t feel you are ready for such responsibilities. I don\'t think aiding in the creation of any item of power is something a novice should ever be involved in; especially one so untested.$B$BBut that\'s not my decision. The powers that be, or at least the ones that do wish to impart such gifts upon you get to decide that.$B$BIf you\'re interested in learning more, I suggest you seek out Menara Voidrender in Ratchet. She usually resides in the tower above the port town.' WHERE `word_id` = 139342; -- locales_quest - details : entry=4738
UPDATE `trans_words` SET `content_loc10`='Let us begin, mortal.$B$BThere is little time to spare.' WHERE `word_id` = 190882; -- locales_quest - offerrewardtext : entry=29452
UPDATE `trans_words` SET `content_loc10`='Let us find this journal. We\'re getting close to the World Pillar fragment, I can sense it.' WHERE `word_id` = 180460; -- locales_quest - offerrewardtext : entry=26261
UPDATE `trans_words` SET `content_loc10`='Let us hope for the safety of those released prisoners. In return for your noble efforts, please accept this gift.' WHERE `word_id` = 179126; -- locales_quest - offerrewardtext : entry=25888
UPDATE `trans_words` SET `content_loc10`='Let us hope that distraction bought us the time we need to fully learn what we need of the training grounds at Karabor.' WHERE `word_id` = 151806; -- locales_quest - offerrewardtext : entry=10637
UPDATE `trans_words` SET `content_loc10`='Let us hope that this ointment will strengthen her spirit!' WHERE `word_id` = 147105; -- locales_quest - offerrewardtext : entry=9463
UPDATE `trans_words` SET `content_loc10`='Let us hope that your work has bought us the time we need...' WHERE `word_id` = 179360; -- locales_quest - offerrewardtext : entry=25942
UPDATE `trans_words` SET `content_loc10`='Let us not be confined by the bounds of the mage repertoire of magic. I, for one, choose not to be classist. Necromancy can just be so much fun!$B$BTouch the Shadow Crystal to open a portal to my Trial of Shadow. Once there, move to the Altar when you are ready to begin.$B$BWeeping Souls shall begin to pursue you... your goal is simply to drag them into the traps. And be sure not to let them touch you.' WHERE `word_id` = 174725; -- locales_quest - details : entry=24479
UPDATE `trans_words` SET `content_loc10`='Let us not mince words, $R; my time here is limited.$B$BYou must destroy the triad of power which protects the demon lord, Razelikh. Doing so will not be as simple a task as freeing a damned soul.$B$B<Kirith grins.>$B$BYou see, each of Razelikh\'s underlings wears a third of an amulet of Razelikh\'s creation around their neck. The very same amulet you will need in order to summon the arch demon.$B$BReturn to Trebor and tell him what is required to summon Razelikh. He will be able to instruct you further.' WHERE `word_id` = 137054; -- locales_quest - details : entry=2743
UPDATE `trans_words` SET `content_loc10`='Let us observe a minute of silence for our fallen mates, $N.$B$B<The Bloodsail Traitor grins at you and winks.>$B$BBeing a traitor is one thing, murdering yer own buckos... that\'d be just downright despicable, aye!' WHERE `word_id` = 145289; -- locales_quest - offerrewardtext : entry=9259
UPDATE `trans_words` SET `content_loc10`='Let us proceed.' WHERE `word_id` = 191506; -- locales_quest - offerrewardtext : entry=30098
UPDATE `trans_words` SET `content_loc10`='Let us see how well they fight without their weapons.' WHERE `word_id` = 184056; -- locales_quest - offerrewardtext : entry=27311
UPDATE `trans_words` SET `content_loc10`='Let us see if we can further weaken the resolve of the vrykul, $N.$B$BEach day I wish you to travel to Jotunheim and put their banners to the torch. It may seem a trivial thing, but to see their ancestral home vandalized on a daily basis will demoralize them more than any physical punishment you can inflict.$B$BAt least... it can\'t hurt.' WHERE `word_id` = 162481; -- locales_quest - details : entry=13084
UPDATE `trans_words` SET `content_loc10`='Let\'s begin our lesson at once!' WHERE `word_id` = 148243; -- locales_quest - offerrewardtext : entry=9757
UPDATE `trans_words` SET `content_loc10`='Let\'s get one thing straight, $N: I don\'t trust you. But, with the situation as it is, you probably won\'t make a difference.$B$BSo here\'s how it\'s going to be: go down there and have your talk with Thredd. If you\'re really on our side, then kill him and bring me his head when the job\'s done. And if it turns out you\'re on his side, and don\'t come out... when we find you, you\'ll die along with the rest of the maggots.' WHERE `word_id` = 131804; -- locales_quest - details : entry=391
UPDATE `trans_words` SET `content_loc10`='Let\'s get some work done, shall we?  I\'ve got a new spell for you. You interested?$B$BThis spell won\'t work like anything you\'ve previously learned. Each time you cast another spell, there\'s a chance you\'ll have an opening to cast Arcane Missiles.' WHERE `word_id` = 175829; -- locales_quest - details : entry=24965
UPDATE `trans_words` SET `content_loc10`='Let\'s get to work!' WHERE `word_id` = 141955; -- locales_quest - offerrewardtext : entry=7261
UPDATE `trans_words` SET `content_loc10`='Let\'s get you started. The good news is that by defeating Agnetta, you\'ve earned yourself a spot in the next round of matches.$B$BThe bad news is that all your opponents will also have defeated someone in the first round. Do not expect pushovers.' WHERE `word_id` = 162020; -- locales_quest - details : entry=12971
UPDATE `trans_words` SET `content_loc10`='Let\'s go fishing, $N! Now that the mortars are ready, we can take out the leader of this invasion.$B$BFathom-Lord Heth\'Jatar rules over the Blackscale warrior caste. Go to the Heth\'Jatari Banners just northeast of here and honk this conch shell. It\'s like a dog-whistle. For fish.$B$BWhen Heth\'Jartar shows up, I\'ll order the mortars to concentrate fire. You\'ll see the targets of the incoming shells.$B$BLure Heth\'Jatar into our mortar fire and pummel him into submission!' WHERE `word_id` = 185083; -- locales_quest - details : entry=27606
UPDATE `trans_words` SET `content_loc10`='Let\'s go!' WHERE `word_id` = 128287; -- locales_quest - offerrewardtext : entry=1191
UPDATE `trans_words` SET `content_loc10`='Let\'s have a look at that...$B$BThis seems simple enough. They have their own names for some of the herbs, but those are simple enough to figure out. Here, let me show you!' WHERE `word_id` = 143276; -- locales_quest - offerrewardtext : entry=8313
UPDATE `trans_words` SET `content_loc10`='Let\'s have a look then... Mmm, oh dear. That\'s what I thought these were. They might still be usable, but it\'s horrid to have such things in my backyard.' WHERE `word_id` = 185889; -- locales_quest - offerrewardtext : entry=27818
UPDATE `trans_words` SET `content_loc10`='Let\'s have a look, $C.' WHERE `word_id` = 172356; -- locales_quest - offerrewardtext : entry=13620
UPDATE `trans_words` SET `content_loc10`='Let\'s hope we put down enough of them to get the message across.' WHERE `word_id` = 187954; -- locales_quest - offerrewardtext : entry=28357
UPDATE `trans_words` SET `content_loc10`='Let\'s hope your efforts prove to be enough of a diversion...' WHERE `word_id` = 177207; -- locales_quest - offerrewardtext : entry=25357
UPDATE `trans_words` SET `content_loc10`='Let\'s just get it out in the open. I\'m no stranger to love, $N.$B$BOver the years, if there\'s one thing I\'ve learned, it\'s that love\'s tangible treasures last longer than the flames of passion.$B$BI\'ve managed to collect my fair share of these gifts - gemstones, rings, necklaces, and the like, and I carry them with me wherever I go.$B$BAt least I used to...$B$BWhen I was swept from the ship, my valuables were scattered across the sea. Help me recover them and I promise to make it worth your trouble.' WHERE `word_id` = 177313; -- locales_quest - details : entry=25390
UPDATE `trans_words` SET `content_loc10`='Let\'s just hope we don\'t have to deal with their mommy later. That would be very bad.' WHERE `word_id` = 174472; -- locales_quest - offerrewardtext : entry=14473
UPDATE `trans_words` SET `content_loc10`='Let\'s not be wasteful here, babe. These pirates have tons of valuable nonsense just sitting around, waiting to be fenced. Can you believe they just sit on this stuff?$B$BI mean, why do they even bother taking it if it\'s just going to sit around? Stolen goods should be sold off and used to buy shiny new things.$B$BAnyway, be a dear and go grab as much of their loot as you can carry while you\'re out busting heads. Ciao!' WHERE `word_id` = 175751; -- locales_quest - details : entry=24949
UPDATE `trans_words` SET `content_loc10`='Let\'s not leave Captain O\'Breen waiting. He\'ll want to see these gems first hand. After all, that\'s why we\'re here!$B$BAnd after a few weeks of consorting with these pirates, the professor and I have realized the last thing that\'s good for our health is to be caught hanging on to their treasure.$B$BHere, $N, take these to O\'Breen.' WHERE `word_id` = 132996; -- locales_quest - details : entry=26052
UPDATE `trans_words` SET `content_loc10`='Let\'s not waste more of my precious time with jibber jabber, $N. It\'s time to focus on replenishing our dwindling fiery flux supply.$BWhat I\'m gonna need from you is the following:$B$B*2 Incendosaur scales.$B*4 Kingsblood.$B*1 Coal.$B$BI\'ll take all that you can offer!$BAnd you\'ll do it fast if you wanna get in good with the Brotherhood.' WHERE `word_id` = 142437; -- locales_quest - details : entry=7736
UPDATE `trans_words` SET `content_loc10`='Let\'s not waste more of my precious time with jibber jabber, $R. It\'s time to focus on replenishing our dwindling fiery flux supply.$B$BWhat I\'m gonna need from you is the following:$B$B*Incendosaur scales.$B$B*Heavy Leather.$B$B*Coal.$B$BI\'ll take all that you can offer!$B$BAnd you\'ll do it fast if you wanna get in good with the Brotherhood.' WHERE `word_id` = 276039; -- locales_quest - details : entry=8242
UPDATE `trans_words` SET `content_loc10`='Let\'s not waste more of my precious time with jibber jabber, $R. It\'s time to focus on replenishing our dwindling fiery flux supply.$B$BWhat I\'m gonna need from you is the following:$B$B*Incendosaur scales.$B$B*Iron bars.$B$B*Coal.$B$BI\'ll take all that you can offer!$B$BAnd you\'ll do it fast if you wanna get in good with the Brotherhood.' WHERE `word_id` = 143088; -- locales_quest - details : entry=8241
UPDATE `trans_words` SET `content_loc10`='Let\'s see here... what do we have...$B$B<Keritose buries his head in the papers for a bit, seemingly gleaning little that he did not already know. Suddenly he finds what he is looking for...>$B$BMalykriss! The Vile Hold. It seems Arthas did not take the loss of his death knights so well... I\'m not exactly sure what he\'s doing with all of that Saronite, but I have a feeling he might be overcompensating for something.$B$BThat boy is not used to losing.' WHERE `word_id` = 162922; -- locales_quest - offerrewardtext : entry=13174
UPDATE `trans_words` SET `content_loc10`='Let\'s see here...$B$BOh my! Milly\'s grapes have been saved! When she told me that brigands overran her vineyards I nearly despaired, but my faith in the Light did not waver!$B$BAnd through your bravery, we now have grapes for more wine! May the Light bless you, $N, and keep you safe!' WHERE `word_id` = 138586; -- locales_quest - offerrewardtext : entry=3905
UPDATE `trans_words` SET `content_loc10`='Let\'s see if the snare can ground something larger than a drake.' WHERE `word_id` = 182274; -- locales_quest - offerrewardtext : entry=26768
UPDATE `trans_words` SET `content_loc10`='Let\'s see them bring her back to life without her head!$B$B<The high executor\'s laugh draws a number of furtive glances.>$B$BI\'m a little concerned that you let this grand admiral get away, but you\'re still the hero of the day, $N!$B$BTake your pick... you\'ve earned it!' WHERE `word_id` = 159367; -- locales_quest - offerrewardtext : entry=12285
UPDATE `trans_words` SET `content_loc10`='Let\'s see them wage their war now!' WHERE `word_id` = 184053; -- locales_quest - offerrewardtext : entry=27310
UPDATE `trans_words` SET `content_loc10`='Let\'s see what I can do with these...' WHERE `word_id` = 189364; -- locales_quest - offerrewardtext : entry=28837
UPDATE `trans_words` SET `content_loc10`='Let\'s see what we\'ve got here.... By Elune, his notes are scrawled in a half dozen languages. What is this, blood? This archive makes my flesh seethe, but at least it\'s secure. It will take us some time to decipher these notes. Oh - your reward? Yes, here. Nice work with those undead scavengers. Now get back to the fight.' WHERE `word_id` = 172588; -- locales_quest - offerrewardtext : entry=13844
UPDATE `trans_words` SET `content_loc10`='Let\'s see what you\'ve brought me...$B$B<He holds the phial up to the light and examines it closely.>$B$BYes, this will do. Well done, $N.' WHERE `word_id` = 146875; -- locales_quest - offerrewardtext : entry=9403
UPDATE `trans_words` SET `content_loc10`='Let\'s see, let\'s see.$B$BIt looks like the artillery shells are prepped here, then loaded into the secure magazine...$B$B<Weezil rubs his hands together.>$B$B$N, are you ready to blow some stuff up?' WHERE `word_id` = 175238; -- locales_quest - offerrewardtext : entry=24685
UPDATE `trans_words` SET `content_loc10`='Let\'s see... oh, here\'s a good one! Silithus!$B$BSo, apparently the Cenarion Circle needs assistance with an insect infestation of some sort.$B$B<Vizzie shivers.>$B$BUgh! No thanks, not for me. I\'m pefectly happy freezing to death here in Everlook if the alternative is bugs.$B$BHmm... it says here that visitors should speak with Windcaller Proudhorn, and the easiest way to get there is via the path up Un\'Goro Crater\'s northwestern cliffs.$B$BYou interested?' WHERE `word_id` = 189433; -- locales_quest - details : entry=28856
UPDATE `trans_words` SET `content_loc10`='Let\'s see... Overseer Maltorius... we\'re quite familiar with him and his work. What\'s this?  The "archduke"?  That sounds promising.' WHERE `word_id` = 186403; -- locales_quest - offerrewardtext : entry=27963
UPDATE `trans_words` SET `content_loc10`='Let\'s send word back to old Anselm then. Victory has come later than expected, but better late than never. Tell him it will take our forces a few hours at most to finish off the stragglers here.$B$BGlory to the Banshee Queen!' WHERE `word_id` = 155324; -- locales_quest - details : entry=11234
UPDATE `trans_words` SET `content_loc10`='Let\'s start with the basics, shall we?  I\'m the only rogue trainer in town, so you\'re going to have to learn it from me.$B$BHere\'s how it\'s going to go: you give me your money, and I\'ll teach you how to finish off a foe. Do we have a deal?' WHERE `word_id` = 176475; -- locales_quest - details : entry=25141
UPDATE `trans_words` SET `content_loc10`='Let\'s start you off with something straightforward. The male vrykul that work the mines for us do so against their will... purely out of fear of our blades.$B$BOnce in a while, one of them will lose their motivation. Find any uncooperative vrykul and put them in their place.$B$BTake this disciplining rod. You\'ll want to inflict pain, not death. Well, most of the time anyway.' WHERE `word_id` = 161745; -- locales_quest - details : entry=12906
UPDATE `trans_words` SET `content_loc10`='Let\'s start your training right away. I want to teach you a combat technique that you\'ll find useful at the start of battle. By charging your opponent before the fight begins, you can stun the enemy and momentum will be on your side.$B$BI want you to try out this technique using the training dummies to the northwest of the Crash Site. Return to me when you think you\'ve mastered it.' WHERE `word_id` = 182933; -- locales_quest - details : entry=26958
UPDATE `trans_words` SET `content_loc10`='Let\'s start your training right away. It\'s going to be a struggle to survive here, and you\'ll play an important role in making sure our people are safe and well-supplied. I want to show you a shooting technique that I use all the time.$B$BTry out this technique using the training dummies to the northwest of the Crash Site. Return to me when you think you\'ve mastered it.' WHERE `word_id` = 182953; -- locales_quest - details : entry=26963
UPDATE `trans_words` SET `content_loc10`='Let\'s take a closer look at these weapons, $N. Hmmm... this is rather unsettling.' WHERE `word_id` = 151608; -- locales_quest - offerrewardtext : entry=10587
UPDATE `trans_words` SET `content_loc10`='Let\'s take a look here.$B$BOh, this is just lovely. "Significant geological instabilities"? "Threat of sudden, massive topological destabilization"?$B$BNice to hear that somethin\' bad might happen around here. I guess we\'ll just pick up our flooded town and fly it off somewhere safe!$B$BBah!' WHERE `word_id` = 178723; -- locales_quest - offerrewardtext : entry=25777
UPDATE `trans_words` SET `content_loc10`='Let\'s try it then. Let\'s see what fel orc crafting is all about.' WHERE `word_id` = 152235; -- locales_quest - offerrewardtext : entry=10763
UPDATE `trans_words` SET `content_loc10`='Lets put dose skills ta use. I\'ll start ya off easy, mon.$B$BThere be cats killing our boars. Dat food ain\'t for sharin\'. Dose boars are gonna need ta be alive if ya be wanting food tonight.$B$BDey\'re all over the island. Bring me some cat pelts.' WHERE `word_id` = 175151; -- locales_quest - details : entry=24641
UPDATE `trans_words` SET `content_loc10`='Letter from Saurfang read and destroyed' WHERE `word_id` = 158231; -- locales_quest - EndText : entry=12033
UPDATE `trans_words` SET `content_loc10`='Ley line focus information retrieved' WHERE `word_id` = 158371; -- locales_quest - ObjectiveText1 : entry=12065
UPDATE `trans_words` SET `content_loc10`='Leyara has been spotted in the Igneous Depths. A group of Shadow Wardens has cornered her.$B$BGo there immediately. I will join you as soon as I make one necessary preparation.' WHERE `word_id` = 190427; -- locales_quest - details : entry=29203
UPDATE `trans_words` SET `content_loc10`='Leyara... she lives. I sense Fandral\'s hand at play here...' WHERE `word_id` = 190391; -- locales_quest - offerrewardtext : entry=29195
UPDATE `trans_words` SET `content_loc10`='Leyara\'s tale is a tragic one. It pains me that it came to this.$B$BStaghelm must be stopped, before he drags anyone else down with him.' WHERE `word_id` = 190429; -- locales_quest - offerrewardtext : entry=29203
UPDATE `trans_words` SET `content_loc10`='Ley-Guardian Eregos Defeated' WHERE `word_id` = 162687; -- locales_quest - ObjectiveText1 : entry=13128
UPDATE `trans_words` SET `content_loc10`='Ley-Keeper Velania wants you to kill 5 Manawraiths and 5 Mana Stalkers.' WHERE `word_id` = 146052; -- locales_quest - objectives : entry=8486
UPDATE `trans_words` SET `content_loc10`='Liam is right. We must get everyone to higher ground. You must help me spread the word while I manage the logistics of the evacuation.' WHERE `word_id` = 174241; -- locales_quest - offerrewardtext : entry=14397
UPDATE `trans_words` SET `content_loc10`='Librarian Donathan on Amber Ledge wants you to collect the Beryl Prison Key from one of the Beryl Mage Hunters at Beryl Point and use it to release a trapped mage from an arcane prison.' WHERE `word_id` = 156916; -- locales_quest - objectives : entry=11587
UPDATE `trans_words` SET `content_loc10`='Librarian Garren at Amber Ledge wants you to use the Arcanometer at Winterfin Caverns.' WHERE `word_id` = 161002; -- locales_quest - objectives : entry=12728
UPDATE `trans_words` SET `content_loc10`='Librarian Normantis on Amber Ledge wants you to use the Neural Needler on the Imprisoned Beryl Sorcerer until he reveals the location of Lady Evanor.' WHERE `word_id` = 157208; -- locales_quest - objectives : entry=11648
UPDATE `trans_words` SET `content_loc10`='Librarian Serrah in the Transitus Shield needs you to kill Arcane Serpents near the Nexus and collect 5 Nexus Mana Essences from them.' WHERE `word_id` = 157846; -- locales_quest - objectives : entry=11914
UPDATE `trans_words` SET `content_loc10`='Librarian Serrah in the Transitus Shield wants you to gather 10 Frostberries from the Frostberry Bushes in Coldarra.' WHERE `word_id` = 157836; -- locales_quest - objectives : entry=11912
UPDATE `trans_words` SET `content_loc10`='Librarian Serrah wants you to enter the Nexus and recover Berinand\'s Research.' WHERE `word_id` = 162528; -- locales_quest - objectives : entry=13094
UPDATE `trans_words` SET `content_loc10`='Librarian Serrah wants you to speak to Corastrasza in Coldarra.' WHERE `word_id` = 163802; -- locales_quest - objectives : entry=13412
UPDATE `trans_words` SET `content_loc10`='Lich King Defeated' WHERE `word_id` = 165148; -- locales_quest - ObjectiveText1 : entry=24748
UPDATE `trans_words` SET `content_loc10`='Lieutenant Amadi in Honor Hold wants you to bring 1 Cursed Talisman to Corporal Ironridge at Expedition Point.' WHERE `word_id` = 151209; -- locales_quest - objectives : entry=10483
UPDATE `trans_words` SET `content_loc10`='Lieutenant Dawnrunner at Farstrider Retreat has requested an audience with all able hunters. It would greatly benefit you to seek her out, $N. She is a beacon of wisdom for those of our calling.$B$BFarstrider Retreat lies south of Silvermoon City.' WHERE `word_id` = 147702; -- locales_quest - details : entry=10529
UPDATE `trans_words` SET `content_loc10`='Lieutenant Dawnrunner at the Farstrider Retreat in Eversong Woods wants you to kill 5 Amani Berserkers and 5 Amani Axe Throwers.' WHERE `word_id` = 146022; -- locales_quest - objectives : entry=8476
UPDATE `trans_words` SET `content_loc10`='Lieutenant Dumont at Amberpine Lodge wants you to go to Evergreen Trading Post and obtain the Cedar Chest.' WHERE `word_id` = 159400; -- locales_quest - objectives : entry=12292
UPDATE `trans_words` SET `content_loc10`='Lieutenant Dumont at Amberpine Lodge wants you to speak to Samir at Granite Springs.' WHERE `word_id` = 158999; -- locales_quest - objectives : entry=12210
UPDATE `trans_words` SET `content_loc10`='Lieutenant Dumont wants you to go to Forest\'s Edge Post and slay Vladek and 7 Silverbrook Hunters.' WHERE `word_id` = 159473; -- locales_quest - objectives : entry=12310
UPDATE `trans_words` SET `content_loc10`='Lieutenant Fairweather has tasked you with slaying 10 Bloodmaul Maulers and 5 Bloodmaul Warlocks. Afterward, return to her at Evergrove in the Blade\'s Edge Mountains.' WHERE `word_id` = 152374; -- locales_quest - objectives : entry=10796
UPDATE `trans_words` SET `content_loc10`='Lieutenant Gebler:$B$BHow curious that you would decide to take a prisoner... an undead one at that. What were you thinking?  Do you think that, just because of the prisoner\'s former status, that she would be above the edicts of the Scarlet Crusade?$B$BThis is most troubling, Gebler. I would remind you that there are penalties for such behavior. I command you to execute the prisoner at once. She is no longer one of us.' WHERE `word_id` = 175886; -- locales_quest - details : entry=24979
UPDATE `trans_words` SET `content_loc10`='Lieutenant General Orion at the Dark Portal in Hellfire Peninsula wants you to bring Orion\'s Report to Vlagga Freyfeather.' WHERE `word_id` = 149729; -- locales_quest - objectives : entry=10120
UPDATE `trans_words` SET `content_loc10`='Lieutenant Gravelhammer asks that you kill 14 Shienor Talonites and 6 Shienor Sorcerers and then return to him in Allerian Stronghold.' WHERE `word_id` = 152702; -- locales_quest - objectives : entry=10869
UPDATE `trans_words` SET `content_loc10`='Lieutenant Icehammer in the Howling Fjord wants you to destroy the Dragonflayer Longhouse, Dragonflayer Dockhouse, Dragonflayer Storage Facility and 8 Dragonflayer Defenders.$B$BReturn the Harpoon Control Mechanism to him once the task is complete.' WHERE `word_id` = 156544; -- locales_quest - objectives : entry=11421
UPDATE `trans_words` SET `content_loc10`='Lieutenant Icehammer in the Howling Fjord wants you to place the Alliance Banner in Baleheim and then defend the banner against attackers.$B$BReturn to Lieutenant Icehammer with the Alliance Banner should you survive.' WHERE `word_id` = 156580; -- locales_quest - objectives : entry=11429
UPDATE `trans_words` SET `content_loc10`='Lieutenant Icehammer in the Howling Fjord wants you to slay Harpoon Master Yavus at Nifflevar.' WHERE `word_id` = 156586; -- locales_quest - objectives : entry=11430
UPDATE `trans_words` SET `content_loc10`='Lieutenant Meridian wants you to use The Final Code to set off the Mana Bomb. Then report back to Jenai Starwhisper at the Allerian Stronghold in Terokkar Forest.' WHERE `word_id` = 151088; -- locales_quest - objectives : entry=10446
UPDATE `trans_words` SET `content_loc10`='Lieutenant Murp in Wintergrasp Fortress wants you to destroy 3 Alliance siege machines.' WHERE `word_id` = 162959; -- locales_quest - objectives : entry=13185
UPDATE `trans_words` SET `content_loc10`='Lieutenant Murp in Wintergrasp wants you to defend or pilot a siege vehicle while they destroy three Alliance structures.$B$BSiege devices can be built by ranked Horde players at the Goblin Workshops.' WHERE `word_id` = 163108; -- locales_quest - objectives : entry=13223
UPDATE `trans_words` SET `content_loc10`='Lieutenant Sinclari in the Violet Hold wants you to put an end to the blue dragon invasion force. You are to speak to her again once Cyanigosa is slain.' WHERE `word_id` = 191417; -- locales_quest - objectives : entry=29830
UPDATE `trans_words` SET `content_loc10`='Lieutenant Vieron Blazefeather at Wintergrasp Fortress wants you to retrieve 10 Quivers of Dragonbone Arrows from Alliance players in the Forest of Shadows.' WHERE `word_id` = 163001; -- locales_quest - objectives : entry=13193
UPDATE `trans_words` SET `content_loc10`='Lieutenant Vieron Blazefeather in Wintergrasp wants you to retrieve 10 Quivers of Dragonbone Arrows from Alliance players at the Forest of Shadows.' WHERE `word_id` = 163016; -- locales_quest - objectives : entry=13199
UPDATE `trans_words` SET `content_loc10`='Lieutenant Wright wants you to kill 10 Orc Invaders.' WHERE `word_id` = 173143; -- locales_quest - objectives : entry=14027
UPDATE `trans_words` SET `content_loc10`='Lieutenant-Sorcerer Morran at Kirin\'Var Village wants you to capture 10 Energy Isolation Cubes from the blood elf operations at Manaforge Coruu.' WHERE `word_id` = 150228; -- locales_quest - objectives : entry=10239
UPDATE `trans_words` SET `content_loc10`='Life in the Burning Steppes is rife with conflict.$B$BJust look at this place! We know very little of what happened to these buildings, but we do know that at one time, before the great explosion, this was all part of the Redridge mountain range.$B$BEnough lamenting! We have a problem, $N. You may have noticed the dragonkin below this ridge. We need assistance in pushing them back. Kill as many as you can and return to me. Succeed and perhaps we can talk of other things.' WHERE `word_id` = 271067; -- locales_quest - details : entry=4182
UPDATE `trans_words` SET `content_loc10`='Life in Westfall\'s hard, $G sonny:missy;! Every day is a struggle. We can sometimes go weeks without a decent meal. That\'s why it\'s important that we all help each other out. Maybe you can lend a hand, eh? I\'m making dirt pies and need some ingredients.$B$BGet me some fresh dirt from the pumpkin patch out front and a bundle of coyote tails. You\'ll find coyotes wandering around in the wilds of Westfall.$B$BGet moving! We got mouths to feed.' WHERE `word_id` = 180337; -- locales_quest - details : entry=26230
UPDATE `trans_words` SET `content_loc10`='Life Rockets Delivered' WHERE `word_id` = 175620; -- locales_quest - ObjectiveText1 : entry=24910
UPDATE `trans_words` SET `content_loc10`='Life\'s tossed me a cartload of lemons this time! When the ship ran aground, the kegs carrying my best brew burst! All we have now are a few bottles of rum, and it won\'t sustain a thirsty expedition!$B$BWe need to get some booze cooking, and fast!!$B$BThe trees in the Wildgrowth Mangal, to the east, seem laden with fruit, but it\'s too high for me to reach. Look for good, strong vines, see if you can use it to shake some of that fruit out of the trees. Bring me whatever you can find.' WHERE `word_id` = 160540; -- locales_quest - details : entry=12634
UPDATE `trans_words` SET `content_loc10`='Lifeblood Energy Recovered' WHERE `word_id` = 161292; -- locales_quest - ObjectiveText1 : entry=12805
UPDATE `trans_words` SET `content_loc10`='Lifebringer Sapling Tested' WHERE `word_id` = 172833; -- locales_quest - ObjectiveText1 : entry=13925
UPDATE `trans_words` SET `content_loc10`='Light be praised, I knew you\'d do it! Arazzius and his minions are no more! Soon, we\'ll have the Legion running for home and this battered world will be safe once more. Then, when justice has been met, we can return home as well.$B$BThanks you, $N - the Alliance and the Sons of Lothar honor you this day!' WHERE `word_id` = 150888; -- locales_quest - offerrewardtext : entry=10400
UPDATE `trans_words` SET `content_loc10`='Light explodes as you finish the incantation. The sounds of the water drops hitting the flame have died down and your senses are overcome as the corrupt spirits around you are destroyed.' WHERE `word_id` = 130544; -- locales_quest - details : entry=100
UPDATE `trans_words` SET `content_loc10`='Light the Sacred Fire of Life' WHERE `word_id` = 139825; -- locales_quest - EndText : entry=5088
UPDATE `trans_words` SET `content_loc10`='Light! Don\'t bring things like that into the Lodge... it\'s unsanitary, unspeakable, un... un... unsanitary!$B$BJust get it out of here, will you? No one wants to see your bloody little trophy, really!' WHERE `word_id` = 132412; -- locales_quest - details : entry=27037
UPDATE `trans_words` SET `content_loc10`='Lightforge Iron is a precious metal, but it sounds like your quest is a dire one. You\'ve come a long way, $GBrother:Sister;. With luck, you might just find what you seek!$B$BAnd if you do get the iron, I know who can fashion it into a weapon against this Necromancer you speak of in Duskwood.' WHERE `word_id` = 131279; -- locales_quest - offerrewardtext : entry=270
UPDATE `trans_words` SET `content_loc10`='Lighthouse Fire Lit' WHERE `word_id` = 172716; -- locales_quest - ObjectiveText1 : entry=13890
UPDATE `trans_words` SET `content_loc10`='Lightning Strikes Absorbed' WHERE `word_id` = 151883; -- locales_quest - ObjectiveText1 : entry=10657
UPDATE `trans_words` SET `content_loc10`='Like a well-oiled machine.' WHERE `word_id` = 186911; -- locales_quest - offerrewardtext : entry=28108
UPDATE `trans_words` SET `content_loc10`='Like any good bloodmage, I perform my magic with blood. All blood is different, and the Blasted Lands has several useful flavors, if you know where to look.$B$BFor our purposes?  Basilisks and hyenas, even amounts. We\'re going to need plenty of it. Head west, to the center of the Blasted Lands. And don\'t forget... you can use that teleporter!' WHERE `word_id` = 180106; -- locales_quest - details : entry=26159
UPDATE `trans_words` SET `content_loc10`='Like Bouldercrag, I once served the keepers as a craftsman in Ulduar, but with Loken\'s betrayal, I turned my hammer toward our new foes.$B$BWhen we could spare the men, I led raids on Nidavelir to relieve the pressure on our defenders, but our lines are near collapse.$B$BYou\'ve proven yourself a capable combatant and a staunch ally. Perhaps you\'d be willing to take up our banner and take the fight to Nidavelir, the iron dwarf stronghold to the southwest, across the Snowdrift Plains.' WHERE `word_id` = 162054; -- locales_quest - details : entry=12978
UPDATE `trans_words` SET `content_loc10`='Like I said, getting out of here won\'t be easy. Warboss Nekrogg may look like an overgrown brute, but he\'s no simpleton.$B$BHe won\'t let the cage key out of his sight and doesn\'t come down from his tower atop that chunk of wall until he\'s ready to question me or that human he\'s managed to capture.$B$BIt\'s going to take something extraordinary to get him off that wall, but I have an idea. Find one of the grenadiers that patrol the ground along the Southern Rampart and bring me some of his explosives.' WHERE `word_id` = 149857; -- locales_quest - details : entry=10154
UPDATE `trans_words` SET `content_loc10`='Like I said, getting out of here won\'t be easy. Warboss Nekrogg may look like an overgrown brute, but he\'s no simpleton.$B$BHe won\'t let the cage key out of his sight and doesn\'t come down from his tower atop that chunk of wall until he\'s ready to question me or that orc he\'s managed to capture.$B$BIt\'s going to take something extraordinary to get him off that wall, but I have an idea. Find one of the grenadiers that patrol the ground along the Southern Rampart and bring me some of his explosives.' WHERE `word_id` = 149775; -- locales_quest - details : entry=10131
UPDATE `trans_words` SET `content_loc10`='Like many in our village, I too have lost a loved one to the wilds. Alas, it was my twin brother Malkhor - taken in the same raid as Torntusk\'s mate by the Vilebranch.$B$BSadly, he was not fated to live and was given a swift, brutal execution; his remains fed to the oozes and wolves of the Vilebranch.$B$BIt is too late to save his life but not too late to save his soul. Recover his remains, $N.' WHERE `word_id` = 142581; -- locales_quest - details : entry=7849
UPDATE `trans_words` SET `content_loc10`='Like many of our own priests, your own tribe puts you through rites of passage. These rites often teach priests special abilities that are vital to their survival. I sense that time is upon you even as we speak. You must return to the Valley of Spirits in Orgrimmar and speak to Ur\'kyo. What he teaches you might be very important for the future.' WHERE `word_id` = 140568; -- locales_quest - details : entry=5643
UPDATE `trans_words` SET `content_loc10`='Like the one you found at the Forgotten Pools, there may be fissures at the other oases in the Barrens. If so, then perhaps the fissures are the oases\' source of life.$B$BWe must test this.$B$BHere, take these seeds. They are dead and infertile, but take them to the Stagnant Oasis to the southeast. If there is a fissure there, then place the seeds within it...and observe.' WHERE `word_id` = 133836; -- locales_quest - details : entry=877
UPDATE `trans_words` SET `content_loc10`='Lila\'s pet Nibbler got into my workshop again!$B$BI was making a bracelet, to be delivered today. The work was almost done, except for the gems. I spent all night cutting them, but when I stepped out for a bit of breakfast, the little beast came into my workshop and swallowed every gem in sight!  The thing can digest ANYTHING, and trust me, you\'d break your back trying to pick up its leavings.$B$BI need to get replacement gems fast; the courier is coming in tonight. Help!' WHERE `word_id` = 176356; -- locales_quest - details : entry=25105
UPDATE `trans_words` SET `content_loc10`='Lilian\'s Mission Accomplished' WHERE `word_id` = 176139; -- locales_quest - ObjectiveText1 : entry=25046
UPDATE `trans_words` SET `content_loc10`='Lilith wants a boulder moved inside the observatory, eh? That\'s my business: consolidated materials. I usually don\'t get individual buyers, but hey, I won\'t ask questions.' WHERE `word_id` = 188765; -- locales_quest - offerrewardtext : entry=28609
UPDATE `trans_words` SET `content_loc10`='Limiting the number of Bloodfury Harpies will not be enough. The only true cure for their disease would be to slay their leader, Bloodfury Ripper!$B$BShe is all but a queen to those filthy creatures. Slay her and their numbers will surely diminish.$B$BGo back into the Charred Vale and you will find her along the western hills. She will not be easy to vanquish, but the reward will be great.' WHERE `word_id` = 141168; -- locales_quest - details : entry=6283
UPDATE `trans_words` SET `content_loc10`='Linzy Blackbolt in Dalaran wants you to successfully transmute 5 epic gems with your alchemy skill. Acceptable transmutes include Ametrine, Eye of Zul, Dreadstone, King\'s Amber, and Majestic Zircon.' WHERE `word_id` = 164785; -- locales_quest - objectives : entry=14151
UPDATE `trans_words` SET `content_loc10`='Lion killer, chicken chaser, new Frenzyheart slave...$B$BI know you no want to stay slave, so I tell you what to do. Show you better than the other Frenzyheart hunters and then Rakjak respect you.$B$BUnder sands of south river there a beast that kills wasp, apes, and even wolvar. He called Serfex. You bring claw of Serfex to Rakjak and maybe he release you from slaveness.$B$BHope Dajik teaching you good so Serfex be easy stuff.' WHERE `word_id` = 160075; -- locales_quest - details : entry=12531
UPDATE `trans_words` SET `content_loc10`='Lirastrasza freed' WHERE `word_id` = 185448; -- locales_quest - ObjectiveText1 : entry=27700
UPDATE `trans_words` SET `content_loc10`='Lirastrasza is the last and greatest of the red dragons that the Twilight\'s Hammer captured. They\'re about to kill her, $C.$B$BYou need to take the Elementium Axe and free her from her bonds before they do.' WHERE `word_id` = 185449; -- locales_quest - details : entry=27701
UPDATE `trans_words` SET `content_loc10`='Lirastrasza is the last and greatest of the red dragons that the Twilight\'s Hammer captured. They\'re about to kill her.$B$BI need you to take the Elementium Axe and free her from her bonds.' WHERE `word_id` = 185445; -- locales_quest - details : entry=27700
UPDATE `trans_words` SET `content_loc10`='Lirastraza sent me ahead to the lair, suspecting the black dragon we are seeking may still be here. Judging by the hatchlings, it seems she was not mistaken.' WHERE `word_id` = 187203; -- locales_quest - offerrewardtext : entry=28176
UPDATE `trans_words` SET `content_loc10`='Lissen mon, there be sumthin\' else needs doin fer ol\' Prigmon.$B$BZungam, my good-fer-nuthin\' cousin, be stuck inside Zul\'Aman. He still be alive too - I seen his signal flare just last night!$B$BI should be lettin\' him rot fer gettin\' me tied up in this mess, but he be owin\' me big money.$B$BDo what ya can to help him out, then leave the collectin\' to me!' WHERE `word_id` = 153906; -- locales_quest - details : entry=11165
UPDATE `trans_words` SET `content_loc10`='Lissen up, mon. Dere be dangerous work ta be done!' WHERE `word_id` = 162540; -- locales_quest - offerrewardtext : entry=13097
UPDATE `trans_words` SET `content_loc10`='Lissen, mon.$B$BAt first glance, it be lookin\' like da same old story here - trolls tappin\' into forbidden powah by destroyin\' da very beings dey should be worshippin\'.$B$BWhile dis be true, dere be somethin\' special about dese Drakkari. If what I learned be true, den inside Gundrak dere be a special golem - one like nuthin\' created before!$B$BYa want adventure, mon? Go inside Gundrak and bring me back a piece from dat golem ta study.' WHERE `word_id` = 162599; -- locales_quest - details : entry=13111
UPDATE `trans_words` SET `content_loc10`='Lissen, pal.$B$BI got a friend, who knows a fella, who might just be lookin\' for a $C that knows $Ghis:her; way around a fight.$B$BIf you\'re not afraid to get your hands dirty, head south over the mountains and look for a goblin named Vern.$B$BTell him Drazz sent ya...' WHERE `word_id` = 176327; -- locales_quest - details : entry=25097
UPDATE `trans_words` SET `content_loc10`='Listen $N, that ring is yours, sure... but I can make you a better one!  That design, like I said, is really simple. I am a lot more skilled now, and for the mere fee of thirty silver coins I\'ll spruce it up for you!  Well, a little more than thirty, actually...$B$BI\'m in a tight spot right now; all my material stock is all dried up. If you bring me a bar of silver and a moss agate, I\'ll add a silver and agate lattice to the ring that will give it a little more pizzazz!$B$BTrust me!' WHERE `word_id` = 137527; -- locales_quest - details : entry=2948
UPDATE `trans_words` SET `content_loc10`='Listen $N, we can\'t leave quite yet. I managed to overhear their plans while they were preparing for the ritual sacrifice.$B$BThey\'re planning to use a powerful artifact called the Demon Seed to launch a full scale attack on the Horde. They\'re keeping it under close guard over in that cave.$B$BIf you can get your hands on the Demon Seed, we should take it to my sister Nagala. She\'ll know what to do with it.' WHERE `word_id` = 189834; -- locales_quest - details : entry=29112
UPDATE `trans_words` SET `content_loc10`='Listen as Duarn speaks to Nespirah' WHERE `word_id` = 179278; -- locales_quest - ObjectiveText1 : entry=25922
UPDATE `trans_words` SET `content_loc10`='Listen as Kalaran Windblade tells his story.' WHERE `word_id` = 138077; -- locales_quest - objectives : entry=3441
UPDATE `trans_words` SET `content_loc10`='Listen as Kharan Mighthammer tells his story.' WHERE `word_id` = 139073; -- locales_quest - objectives : entry=4342
UPDATE `trans_words` SET `content_loc10`='Listen carefully, $C, for though we are only beginning, time already grows short and the consequences of our failure are unfathomable.$B$BAn event in the recent past has been obscured from my vision by the most powerful of magics. Its impact, however, has not.$B$BIf action is not taken to change the course of this timeline\'s future, the outcome is clear.$B$BBrace yourself, mortal, and behold the future of Azeroth.' WHERE `word_id` = 189914; -- locales_quest - details : entry=29134
UPDATE `trans_words` SET `content_loc10`='Listen carefully, $C.$B$BThere are three leaders in this region who are commanding the elves, keeping their focus directed on the lumber camp. Slaying them will certainly cause panic and disarray, hopefully enough for us to successfully complete our mission.$B$BWhile you\'re at it, bringing down their scouts can only aid our cause.' WHERE `word_id` = 172605; -- locales_quest - details : entry=13865
UPDATE `trans_words` SET `content_loc10`='Listen carefully, $N. I don\'t know how those ogres got ahold of it, but that thing\'s a titan artifact. I\'m no expert, but just that fact alone makes it probably older than the sand we\'re standing on.$B$BI also know that things like this are nothing but trouble. I don\'t want anything to do with it. Take it south, to the Valley of the Watchers, and give it to a blood elf named Andoren Dawnrise there. And don\'t ask any questions, babe, please.' WHERE `word_id` = 176026; -- locales_quest - details : entry=25018
UPDATE `trans_words` SET `content_loc10`='Listen carefully, $R....' WHERE `word_id` = 172347; -- locales_quest - offerrewardtext : entry=13618
UPDATE `trans_words` SET `content_loc10`='Listen close, sea dawg... the powers of Booty Bay is what keeps us Bloodsail from sailing wheres we like and taking whats we want as rights o\' plunder. Were ye to put a knife to Fleet Master Seahorn, we\'d ne\'er run afoul of a Booty Bay\'s vessel. Were ye to put a knife to Baron Revilgaz, we\'d ne\'er face the law on their terms.$B$BIf ye are to be an honorary admiral amongst us - yes, ADMIRAL, you\'ll puts a knife to both of \'em as I\'ve says. Go now $G lad : lass;, and return to me once ye does the deeds.' WHERE `word_id` = 139255; -- locales_quest - details : entry=4621
UPDATE `trans_words` SET `content_loc10`='Listen closely, $N, for there is not a moment to spare.$B$BYour prisoner is being prepared for interrogation here in our tower. In the event that he is less than forthcoming, your assistance may be required.$B$BMake your way up to where he is being detained and tell Librarian Normantis that I\'ve sent you to assist him.' WHERE `word_id` = 157195; -- locales_quest - details : entry=11646
UPDATE `trans_words` SET `content_loc10`='Listen closely, little $R. Time is of the essence.' WHERE `word_id` = 160515; -- locales_quest - offerrewardtext : entry=12628
UPDATE `trans_words` SET `content_loc10`='Listen closely, mortal.$B$BThe Quilboar are my children. My blood runs deep in these lands.$B$BCharlga Razorflank has steered my children into darkness, driven into insanity by the Scourge.$B$BSlay her, $N. Slay her and open my childrens\' eyes.$B$BGive the Quilboar the chance to return to their noble roots. Let them once more earn my blessing.$B$BBring me her heart!!!' WHERE `word_id` = 182723; -- locales_quest - details : entry=26905
UPDATE `trans_words` SET `content_loc10`='Listen to a speech given by a Doomsayer in Old Town and obtain copies of the pamphlets "Elemental Fire for the Soul", "What Does \'The End of All Things\' Mean for Me?", and "Finding Security and Comfort in a Doomed World".' WHERE `word_id` = 171806; -- locales_quest - objectives : entry=25253
UPDATE `trans_words` SET `content_loc10`='Listen to a speech given by a Doomsayer in the Drag and obtain copies of the pamphlets "Elemental Fire for the Soul", "What Does \'The End of All Things\' Mean for Me?", and "Finding Security and Comfort in a Doomed World".' WHERE `word_id` = 171801; -- locales_quest - objectives : entry=25228
