UPDATE `trans_words` SET `content_loc10`='Listen to Doomsayer\'s speech' WHERE `word_id` = 171804; -- locales_quest - ObjectiveText1 : entry=25228
UPDATE `trans_words` SET `content_loc10`='Listen to Fizzcrank Fullthrottle\'s tale and then find Jinky Wingnut at Fizzcrank Airstrip.' WHERE `word_id` = 157460; -- locales_quest - objectives : entry=11708
UPDATE `trans_words` SET `content_loc10`='Listen to Greatmother Geyah' WHERE `word_id` = 149440; -- locales_quest - EndText : entry=10044
UPDATE `trans_words` SET `content_loc10`='Listen to Lok\'lira the Crone\'s proposal.' WHERE `word_id` = 162015; -- locales_quest - objectives : entry=12970
UPDATE `trans_words` SET `content_loc10`='Listen to Lok\'lira\'s proposal' WHERE `word_id` = 162018; -- locales_quest - ObjectiveText1 : entry=12970
