UPDATE `trans_words` SET `content_loc10`='Prepare Spice Bread Stuffing' WHERE `word_id` = 164597; -- locales_quest - ObjectiveText1 : entry=14023
UPDATE `trans_words` SET `content_loc10`='Prepare the bonfire in Fort Livingston for Bwemba\'s ritual.' WHERE `word_id` = 189803; -- locales_quest - objectives : entry=29104
UPDATE `trans_words` SET `content_loc10`='Prepare the bonfire in front of the serpent shrine near Bambala for Bwemba\'s ritual.' WHERE `word_id` = 190143; -- locales_quest - objectives : entry=29222
UPDATE `trans_words` SET `content_loc10`='Prepare yourself for battle. The Horde has need of you here.' WHERE `word_id` = 189032; -- locales_quest - offerrewardtext : entry=28705
UPDATE `trans_words` SET `content_loc10`='Prepare yourself, $N! The Warlord comes! Kill him and take his key. Use the key to release me.$B$BShould we make it out of here, report the following to Lord Fallowmere at Windshear Hold:$B$BThe Horde has aborted their plans to destroy Windshear Hold due to the efforts of one of our heroes. They now plan to move the bomb to Battlescar Valley and drop it on our armies battling the Horde at that location.$B$BThey must be stopped!' WHERE `word_id` = 178249; -- locales_quest - details : entry=25669
UPDATE `trans_words` SET `content_loc10`='Present a Lovely Charm Bracelet to Cairne Bloodhoof in Thunder Bluff.' WHERE `word_id` = 165286; -- locales_quest - objectives : entry=24614
