UPDATE `trans_words` SET `content_loc10`='Present Arcanist Taelis at the Argent Tournament with 15 Aspirant\'s Seals to signify you\'re ready to undergo the aspirant\'s challenge.' WHERE `word_id` = 164057; -- locales_quest - objectives : entry=13672
UPDATE `trans_words` SET `content_loc10`='Present Magister Edien Sunhollow at the Argent Tournament with 15 Aspirant\'s Seals to signify you\'re ready to undergo the aspirant\'s challenge.' WHERE `word_id` = 164069; -- locales_quest - objectives : entry=13678
