UPDATE `trans_words` SET `content_loc10`='Press the Big Red Button to destroy the KTC Oil Platform.' WHERE `word_id` = 176741; -- locales_quest - objectives : entry=25207
UPDATE `trans_words` SET `content_loc10`='Pretty good for a rookie. As it turns out, we\'ve got a small group of eggheads that want to go \'observe\' the ethereals and their technology up north. They\'ll be thrilled to know that you cleared the way for them.$B$BHere, take some of these. We don\'t have many, but maybe they\'ll help you out in the future.' WHERE `word_id` = 151738; -- locales_quest - offerrewardtext : entry=10620
UPDATE `trans_words` SET `content_loc10`='Pretty little things, aren\'t they? I wonder if we can figure out how to make more of them.' WHERE `word_id` = 188005; -- locales_quest - offerrewardtext : entry=28370
UPDATE `trans_words` SET `content_loc10`='Pridelings freed' WHERE `word_id` = 186825; -- locales_quest - ObjectiveText1 : entry=28086
UPDATE `trans_words` SET `content_loc10`='Priestess A\'moora in the Temple of the Moon at Darnassus wants you to bring her Lady Sathrah\'s Silvery Spinnerets.' WHERE `word_id` = 136899; -- locales_quest - objectives : entry=2518
