UPDATE `trans_words` SET `content_loc10`='Priestess is not very good at speaking Common, no.$B$BMaybe you go speak with Ghaliri, in front of that tent.$B$BTell him about what you\'ve seen inside Zul\'Gurub, yes.' WHERE `word_id` = 182295; -- locales_quest - details : entry=26776
