UPDATE `trans_words` SET `content_loc10`='Prigmon has tasked you with locating and assisting his cousin Zungam, somewhere within Zul\'Aman.' WHERE `word_id` = 153907; -- locales_quest - objectives : entry=11165
UPDATE `trans_words` SET `content_loc10`='Prigmon in Granite Springs wants you to collect 5 Shimmering Snowcaps and 5 Ice Serpent Eyes from Drak\'Zin Ruins and 5 Sweetroot from Zeb\'Halak.' WHERE `word_id` = 159876; -- locales_quest - objectives : entry=12483
UPDATE `trans_words` SET `content_loc10`='Prigmon needs you to collect 10 Forest Troll Tusks from the trolls in Zul\'Aman. Bring them to him at Budd\'s camp in the Ghostlands.' WHERE `word_id` = 153902; -- locales_quest - objectives : entry=11164
UPDATE `trans_words` SET `content_loc10`='Prigmon wants you to bring Harkor\'s Ingredients to Harkor at Harkor\'s Camp.' WHERE `word_id` = 158921; -- locales_quest - objectives : entry=12190
UPDATE `trans_words` SET `content_loc10`='Primal Mighthorn will be delighted! This is better than even I expected!$B$BPerhaps it\'s time that I told you the truth.' WHERE `word_id` = 157517; -- locales_quest - offerrewardtext : entry=11719
UPDATE `trans_words` SET `content_loc10`='Primal Torntusk at Revantusk Village in the Hinterlands wants you to recover 10 Vessels of Tainted Blood from Jintha\'alor. Return to Primal Torntusk when this task is complete.' WHERE `word_id` = 142587; -- locales_quest - objectives : entry=7850
UPDATE `trans_words` SET `content_loc10`='Primal Torntusk at Revantusk Village in the Hinterlands wants you to rescue her mate, Elder Torntusk, from Jintha\'alor.$B$BYou have been told that he is being held prisoner atop Jintha\'alor, the Vilebranch capital city located in the southern region of the Hinterlands.' WHERE `word_id` = 142569; -- locales_quest - objectives : entry=7845
UPDATE `trans_words` SET `content_loc10`='Primalist Mulfort in Wintergrasp wants you to retrieve 10 Alliance Herb Pouches from Alliance players at the Steppe of Life.' WHERE `word_id` = 163021; -- locales_quest - objectives : entry=13201
