UPDATE `trans_words` SET `content_loc10`='Release the spirits of 6 tortured souls at Forgotten Hill. Souls can be channeled by touching your hands directly to the gravestones. Forgotten Hill is due west of here, past The Darkwood and The Restless Front.' WHERE `word_id` = 186344; -- locales_quest - objectives : entry=27949
UPDATE `trans_words` SET `content_loc10`='Release the spirits of 6 tortured souls at Forgotten Hill. Souls can be channeled by touching your hands directly to the gravestones. Forgotten Hill is due west of here, past The Restless Front.' WHERE `word_id` = 188995; -- locales_quest - objectives : entry=28689
UPDATE `trans_words` SET `content_loc10`='Release them, $R. Even after their bodies give out, the power of the Suntara forces them to complete their tasks.$B$BThe altar of Suntara is the key. Go northwest; in the hills above the cave... Twilight\'s Hammer guard a relic. Retrieve it and place it on the altar of Suntara.$B$B<The dying archaeologist collapses.>' WHERE `word_id` = 138019; -- locales_quest - details : entry=3372
UPDATE `trans_words` SET `content_loc10`='Release Valves #1 - 4.' WHERE `word_id` = 176723; -- locales_quest - objectives : entry=25204
