UPDATE `trans_words` SET `content_loc10`='Sentinel Luciel Starwhisper at Forest Song wants you to kill Overseer Gorthak, 2 Warsong Shredders, 5 Horde Deforesters, and 10 Horde Scouts.' WHERE `word_id` = 147305; -- locales_quest - objectives : entry=9518
UPDATE `trans_words` SET `content_loc10`='Sentinel Moonwhisper at the tunnel between Zangarmarsh and Blade\'s Edge Mountains wants you to kill 6 Cavern Crawlers and report to Commander Skyshadow in Sylvanaar.' WHERE `word_id` = 152953; -- locales_quest - objectives : entry=10927
UPDATE `trans_words` SET `content_loc10`='Sentinel training 101: take out their leaders and your enemy\'s forces will soon fall apart. We\'re going to do just that, $C.$B$BIsha Gloomaxe is the closest of the Grimtotem chiefs. Let\'s see if we can\'t take her measure.' WHERE `word_id` = 184065; -- locales_quest - details : entry=27314
UPDATE `trans_words` SET `content_loc10`='Sentinel\'s Game Completed' WHERE `word_id` = 185483; -- locales_quest - ObjectiveText1 : entry=27709
UPDATE `trans_words` SET `content_loc10`='Sentry Point explored' WHERE `word_id` = 135278; -- locales_quest - EndText : entry=1265
UPDATE `trans_words` SET `content_loc10`='Sergeant Altumus at the East Supply Caravan east of Honor Hold in Hellfire Peninsula wants you to kill 4 Flamewaker Imps, 6 Infernal Warbringers and 1 Dreadcaller.' WHERE `word_id` = 149819; -- locales_quest - objectives : entry=10142
UPDATE `trans_words` SET `content_loc10`='Sergeant Bly stole from me!  He said he\'d only borrow it, but he stole my cherished divino-matic rod!!  Without that rod how will I know where to dig new water holes??$B$BFind Bly and bring me my rod!  I heard he led his band of ill-reputed adventurers to go treasure hunting in Zul\'Farrak to the west. I bet you\'ll find him there.$B$BLet\'s hope the trolls took care of him, because if you have to fight him for the rod then you\'re in for a serious fight.' WHERE `word_id` = 137162; -- locales_quest - details : entry=2768
UPDATE `trans_words` SET `content_loc10`='Sergeant Chawni wants you to use the Final Code Sheet to set off the Mana Bomb. Then report back to Tooki at Stonebreaker Hold in Terokkar Forest.' WHERE `word_id` = 151093; -- locales_quest - objectives : entry=10447
UPDATE `trans_words` SET `content_loc10`='Sergeant Flinthammer? I\'m not familiar with the name, but, aye, there is a Flinthammer among the miners. He\'s one of the ones lucky enough to make it out of the mine, but most of my men are still trapped down there.' WHERE `word_id` = 179324; -- locales_quest - offerrewardtext : entry=25933
UPDATE `trans_words` SET `content_loc10`='Sergeant Gorth wants you to go to Baleheim and use Gorth\'s Torch to burn 1 Winterskorn Dwelling, 1 Winterskorn Watchtower, 1 Winterskorn Bridge and 1 Winterskorn Barracks.' WHERE `word_id` = 156194; -- locales_quest - objectives : entry=11285
UPDATE `trans_words` SET `content_loc10`='Sergeant Gorth wants you to kill 16 Winterskorn Vrykul inside Baleheim.' WHERE `word_id` = 156185; -- locales_quest - objectives : entry=11283
UPDATE `trans_words` SET `content_loc10`='Sergeant Gray has asked you to kill Commander Largo at Largo\'s Overlook. The overlook is just northeast of the base camp.' WHERE `word_id` = 186517; -- locales_quest - objectives : entry=27991
UPDATE `trans_words` SET `content_loc10`='Sergeant Gray has asked you to recover 15 pieces of Shipyard Lumber from the Wellson Shipyard. The lumber can be recovered from the ghosts in the shipyard or found lying around the premises. The shipyard can be found northwest of here, on the coast.' WHERE `word_id` = 186444; -- locales_quest - objectives : entry=27973
