UPDATE `trans_words` SET `content_loc10`='Serves every last one of them right. Let\'s hope those in charge send the rest of their greedy scavengers somewhere else.' WHERE `word_id` = 188079; -- locales_quest - offerrewardtext : entry=28388
UPDATE `trans_words` SET `content_loc10`='Serves her right for stealing your man in the first place.' WHERE `word_id` = 176871; -- locales_quest - offerrewardtext : entry=25244
