UPDATE `trans_words` SET `content_loc10`='Show the Blackened Iron Shield to Caz Twosprocket in Theramore.' WHERE `word_id` = 135343; -- locales_quest - objectives : entry=1319
UPDATE `trans_words` SET `content_loc10`='Show the Blackened Iron Shield to Do\'gol in Brackenwall Village.' WHERE `word_id` = 135350; -- locales_quest - objectives : entry=1321
UPDATE `trans_words` SET `content_loc10`='Show the Blackened Iron Shield to Mosarn in Thunder Bluff.' WHERE `word_id` = 135312; -- locales_quest - objectives : entry=1276
