UPDATE `trans_words` SET `content_loc10`='Southern Naga Forces slain' WHERE `word_id` = 178603; -- locales_quest - ObjectiveText1 : entry=25748
UPDATE `trans_words` SET `content_loc10`='Southern Naga Forces' WHERE `word_id` = 179416; -- locales_quest - ObjectiveText1 : entry=25959
