UPDATE `trans_words` SET `content_loc10`='Stinkbeard Defeated' WHERE `word_id` = 161868; -- locales_quest - EndText : entry=12933
UPDATE `trans_words` SET `content_loc10`='Stinky was here with the herbs I ask of him, and he told me you helped him out of a bind. Good work! A friend of Stinky\'s is a friend of mine!$B$BHe asked me to give you this if I ever saw you, right before he walked back south toward the marsh.' WHERE `word_id` = 135294; -- locales_quest - offerrewardtext : entry=1270
UPDATE `trans_words` SET `content_loc10`='Stolen Rams recovered' WHERE `word_id` = 179202; -- locales_quest - ObjectiveText1 : entry=25905
UPDATE `trans_words` SET `content_loc10`='Stoma the Ancient has asked that you bring him a Mature Black Dragon Sinew. Should you find this sinew, return it to Stoma in Felwood.' WHERE `word_id` = 142255; -- locales_quest - objectives : entry=7635
UPDATE `trans_words` SET `content_loc10`='Stone Dragons bow only to strength. When we have punished them enough, they will bend back to our will.$B$BI have sent many of my strongest giants onto the fields in the west. They will bring the drakes to the ground. You will see to it that they do not take wing again after they fall.' WHERE `word_id` = 181869; -- locales_quest - details : entry=26657
UPDATE `trans_words` SET `content_loc10`='Stone Guard Stok\'ton inside the Shattered Halls of Hellfire Citadel wants you to bring him a Fel Ember.' WHERE `word_id` = 191266; -- locales_quest - objectives : entry=29650
