UPDATE `trans_words` SET `content_loc10`='Surveying Marker Two placed' WHERE `word_id` = 150676; -- locales_quest - ObjectiveText2 : entry=10335
UPDATE `trans_words` SET `content_loc10`='Surveyor Hansen, just north of the Forgotten Shore, has asked you to slay 20 Forgotten ghosts.' WHERE `word_id` = 159452; -- locales_quest - objectives : entry=12304
UPDATE `trans_words` SET `content_loc10`='Survival kits never have any rope. It makes no sense! No sense at all.$B$BI bet those Kvaldir have rope. They\'re always riding around in boats, tying knots, dressing in nets. Go take some rope from them! I must have it for our plan to work. Absolutely must.' WHERE `word_id` = 179167; -- locales_quest - details : entry=25897
UPDATE `trans_words` SET `content_loc10`='Survival kits never have any rope. It makes no sense! Rope and bombs, that\'s all they should store. The rest of this stuff is just a waste of space.$B$BExcept maybe the balloon. That\'s coming in handy right now.$B$BI bet those Kvaldir have rope. They\'re always riding around in boats, tying knots, dressing in nets. Go take some rope from them! I must have it for our plan to work. It is non-optional.' WHERE `word_id` = 179446; -- locales_quest - details : entry=25971
UPDATE `trans_words` SET `content_loc10`='Survive 2 Massive Waves of Zombies.' WHERE `word_id` = 189166; -- locales_quest - objectives : entry=28744
UPDATE `trans_words` SET `content_loc10`='Survive a Massive Wave of Zombies.' WHERE `word_id` = 188800; -- locales_quest - objectives : entry=28617
