UPDATE `trans_words` SET `content_loc10`='Take Yetimus\' Twisted Horn.' WHERE `word_id` = 188301; -- locales_quest - objectives : entry=28485
UPDATE `trans_words` SET `content_loc10`='Take your Fragile Sprite Darter Egg to the Hinterlands and speak to Agnar Beastamer, but hurry, you only have 1 hour to find him before the hatchling within the egg dies.' WHERE `word_id` = 138531; -- locales_quest - objectives : entry=3843
UPDATE `trans_words` SET `content_loc10`='Take your Human Orphan into Old Ironforge, beneath the High Seat, to visit the resting place of King Magni Bronzebeard. Make sure to call for him if he is not present when you arrive.' WHERE `word_id` = 189813; -- locales_quest - objectives : entry=29106
