UPDATE `trans_words` SET `content_loc10`='Toss Tasty Reef Fish at a Reef Bull to lead it to a Reef Cow. Once you have helped the two to find true love, return to Anuniaq at Kamagua.' WHERE `word_id` = 156695; -- locales_quest - objectives : entry=11472
UPDATE `trans_words` SET `content_loc10`='Toss three Forsaken Stink Bombs into the heart of Southshore in Hillsbrad, and return to Darkcaller Yanka at the Wickerman Festival in Tirisfal Glade.' WHERE `word_id` = 136058; -- locales_quest - objectives : entry=1657
