UPDATE `trans_words` SET `content_loc10`='Totem Tests Performed' WHERE `word_id` = 153922; -- locales_quest - ObjectiveText1 : entry=11169
UPDATE `trans_words` SET `content_loc10`='Touch the bonfires within Orgrimmar, Thunder Bluff, and the Undercity, then speak to a Festival Talespinner within the capital cities.' WHERE `word_id` = 145400; -- locales_quest - objectives : entry=9368
UPDATE `trans_words` SET `content_loc10`='Touch the bonfires within Stormwind, Ironforge, and Darnassus, then speak to a Festival Loremaster within the capital cities.' WHERE `word_id` = 145397; -- locales_quest - objectives : entry=9367
UPDATE `trans_words` SET `content_loc10`='Touch the Eastern Crystal Pylon in Un\'Goro Crater.' WHERE `word_id` = 175373; -- locales_quest - objectives : entry=24721
UPDATE `trans_words` SET `content_loc10`='Touching the Discs of Norgannon once again makes your hand tingle. This time, however, a strange grinding noise is heard from inside the discs.$B$BYour backpack suddenly becomes heavier than it was before. Inside, you discover a miniature version of the discs!$B$BNo doubt, an item of this sort would be invaluable for someone interested in the ancient history of Azeroth. The Explorers\' League in Ironforge is such a group, known throughout the Alliance; perhaps they can make good use of it.' WHERE `word_id` = 136730; -- locales_quest - details : entry=2279
UPDATE `trans_words` SET `content_loc10`='Touching the Discs of Norgannon once again makes your hand tingle. This time, however, a strange grinding noise is heard from inside the discs.$B$BYour backpack suddenly becomes heavier than it was before. Inside, you discover a miniature version of the discs!$B$BNo doubt, an item of this sort would be invaluable for someone interested in the ancient history of Azeroth. The sages of Thunder Bluff are such historians, known throughout the Horde; perhaps they can make good use of it.' WHERE `word_id` = 136734; -- locales_quest - details : entry=2280
UPDATE `trans_words` SET `content_loc10`='Tour of Zul\'Drak complete' WHERE `word_id` = 160686; -- locales_quest - ObjectiveText1 : entry=12663
