UPDATE `trans_words` SET `content_loc10`='Use a Stink Bomb Cleaner to remove any Forsaken Stink Bomb that\'s been dropped on Southshore. Return to Sergeant Hartman in Southshore when you\'re done.' WHERE `word_id` = 143451; -- locales_quest - objectives : entry=8373
