UPDATE `trans_words` SET `content_loc10`='Use Archmage Vargoth\'s Staff to contact the archmage.$B$BIf you lose Archmage Vargoth\'s Staff, speak to Ravandwyr at Area 52 to receive a replacement.' WHERE `word_id` = 347034; -- locales_quest - CompletedText : entry=10192
