UPDATE `trans_words` SET `content_loc10`='Use Bleeding Hollow Blood at the Cursed Cauldron to make Boiled Blood. Bring 12 Boiled Blood to Apothecary Albreck at Spinebreaker Post.' WHERE `word_id` = 151384; -- locales_quest - objectives : entry=10538
UPDATE `trans_words` SET `content_loc10`='Use Bouldercrag\'s War Horn when you have found Valduran the Stormborn. Defeat Valduran the Stormborn and return to Bouldercrag the Rockshaper at Bouldercrag\'s Refuge.' WHERE `word_id` = 162087; -- locales_quest - objectives : entry=12984
