UPDATE `trans_words` SET `content_loc10`='Vindicator Aesom at Blood Watch wants you to use the Water Sample Flask to get a Bloodmyst Water Sample.' WHERE `word_id` = 148220; -- locales_quest - objectives : entry=9748
UPDATE `trans_words` SET `content_loc10`='Vindicator Aluumen wants you to go to the Ruins of Baa\'ri and slay 3 Ashtongue Handlers, 4 Ashtongue Warriors and 6 Ashtongue Shaman.$B$BCompleting quests for the Aldor will cause your Scryers reputation level to decrease.' WHERE `word_id` = 151732; -- locales_quest - objectives : entry=10619
