UPDATE `trans_words` SET `content_loc10`='Zorus the Judicator at Wildhammer Stronghold in Shadowmoon Valley wants you to find the Ancient Shadowmoon Spirit.$B$BIf you lose your Spectrecles, Zorus the Judicator can make you a new pair.' WHERE `word_id` = 273319; -- locales_quest - details : entry=10644
